window.BANQUE_INFINI = {"module":"annee-1/theorique/semestre-2/physio","titre":"Physiologie II","sources":[{"t":"Cours 1 — Système Digestif","q":"qcm/qcm-1-systeme-digestif.html","f":"fiches/fiche-1-systeme-digestif.html"},{"t":"Cours 2 — Système Urinaire","q":"qcm/qcm-2-systeme-urinaire.html","f":"fiches/fiche-2-systeme-urinaire.html"},{"t":"Cours 3 — Équilibre Acido-Basique","q":"qcm/qcm-3-equilibre-acido-basique.html","f":"fiches/fiche-3-equilibre-acido-basique.html"},{"t":"Cours 4 — Système Reproducteur","q":"qcm/qcm-4-systeme-reproducteur.html","f":"fiches/fiche-4-systeme-reproducteur.html"},{"t":"Cours 5 — Physiologie de l'Exercice","q":"qcm/qcm-5-physio-exercice.html","f":"fiches/fiche-5-physio-exercice.html"},{"t":"Cours 6 — Physio de la Vie Quotidienne","q":"qcm/qcm-6-physio-vie-quotidienne.html","f":"fiches/fiche-6-physio-vie-quotidienne.html"}],"questions":[{"q":"Quel est l'ordre correct du tube digestif ?","o":["Bouche → Œsophage → Estomac → Intestin grêle → Gros intestin → Anus","Bouche → Estomac → Œsophage → Gros intestin → Intestin grêle → Anus","Bouche → Pharynx → Estomac → Intestin grêle → Œsophage → Anus","Bouche → Œsophage → Intestin grêle → Estomac → Gros intestin → Anus"],"r":0,"e":"Le trajet correct : Bouche → Pharynx → Œsophage → Estomac → Intestin grêle (duodénum, jéjunum, iléon) → Gros intestin (cæcum, côlon, rectum, canal anal) → Anus.","s":0},{"q":"Combien de fonctions principales le système digestif assure-t-il ?","o":["6","7","8","10"],"r":2,"e":"8 fonctions : Ingestion, Mastication, Propulsion, Mélange, Sécrétion, Digestion, Absorption, Élimination.","s":0},{"q":"Quel est le pH normal de l'estomac ?","o":["6,8 – 7,5","5,6 – 8,0","7,2 – 7,5","1,5 – 2,0"],"r":3,"e":"L'estomac est très acide (1,5–2,0) grâce à l'HCl des cellules pariétales. Cela dénature les protéines et active la pepsine.","s":0},{"q":"Quelles sont les 3 paires de glandes salivaires ?","o":["Sublinguale, parotide et submandibulaire","Pinéale, hypophysaire et parathyroïdienne","Surrénale, mammaire et gastrique","Thymique, splénique et hépatique"],"r":0,"e":"Les 3 paires sont : sublinguale (sous la langue), submandibulaire (sous la mâchoire) et parotide (devant l'oreille).","s":0},{"q":"Quelles sont les 3 parties de l'intestin grêle ?","o":["Cæcum, côlon, rectum","Duodénum, jéjunum, iléon","Œsophage, estomac, pylore","Pharynx, larynx, trachée"],"r":1,"e":"L'intestin grêle se divise en duodénum (1ère partie), jéjunum (milieu) et iléon (dernière partie). Le gros intestin contient cæcum, côlon, rectum, canal anal.","s":0},{"q":"Quel organe sécrète la bile ?","o":["Pancréas","Vésicule biliaire","Foie","Estomac"],"r":2,"e":"Le foie produit la bile (600–1000 ml/jour). La vésicule biliaire ne fait que la stocker et la concentrer avant de la libérer dans le duodénum.","s":0},{"q":"Quel est le rôle principal de la mastication ?","o":["Sécréter les enzymes digestives","Broyer les aliments par les dents","Absorber les premiers nutriments","Stocker les aliments avant la déglutition"],"r":1,"e":"La mastication = broyage des aliments par les dents dans la bouche. Elle augmente la surface de contact pour les enzymes.","s":0},{"q":"Le bolus est :","o":["Une enzyme salivaire qui digère l'amidon","La masse d'aliments mâchés et imprégnés de salive","Le contenu acide de l'estomac, mêlé aux sucs gastriques","Une vésicule du pancréas, remplie d'enzymes"],"r":1,"e":"Le bolus (ou bol alimentaire) est la masse formée dans la bouche après mastication et imprégnation salivaire. Il devient chyme dans l'estomac.","s":0},{"q":"Quelle est la définition du chyme ?","o":["Le bol alimentaire formé dans la bouche, après mastication","Le mélange des aliments et des sécrétions gastriques","Les selles formées dans le côlon","Une enzyme sécrétée par le pancréas"],"r":1,"e":"Le chyme est le mélange semi-liquide formé dans l'estomac par l'action des sécrétions gastriques (HCl + pepsine + mucus) sur le bol alimentaire.","s":0},{"q":"Quelle enzyme commence la digestion des glucides dans la bouche ?","o":["Pepsine","Amylase salivaire","Lipase linguale","Lactase"],"r":1,"e":"L'amylase salivaire (ptyaline) débute la dégradation de l'amidon en maltose dans la cavité orale.","s":0},{"q":"Pendant quelle phase les sécrétions gastriques sont-elles INHIBÉES ?","o":["Phase céphalique","Phase gastrique","Phase intestinale","Phase orale"],"r":2,"e":"La phase intestinale inhibe les sécrétions gastriques quand le pH < 2 ou que des lipides arrivent au duodénum (via sécrétine, CCK, GIP).","s":0},{"q":"Pendant la phase céphalique des sécrétions gastriques, le stimulus est :","o":["La distension de l'estomac par les aliments","Le goût, l'odorat et les souvenirs d'aliments","La présence de chyme acide et gras dans le duodénum","Le pic de gastrine, après le repas"],"r":1,"e":"La phase céphalique est déclenchée par le goût, l'odorat, la vue ou les souvenirs d'aliments → stimulation gastrique via le nerf vague (X). L'influx passe par le nerf vague.","s":0},{"q":"Pendant la phase gastrique, le facteur déclenchant principal est :","o":["Le sommeil, par une stimulation vagale nocturne","La distension de l'estomac par les aliments","La marche, qui accélère la vidange","Les odeurs, perçues avant le repas"],"r":1,"e":"La phase gastrique est déclenchée par la distension de l'estomac et les chémorécepteurs → libération de gastrine → ↑ HCl et pepsinogène. Distension et chémorécepteurs entraînent la libération de gastrine.","s":0},{"q":"Quel est le rôle principal de la veine porte hépatique ?","o":["Transporter le sang oxygéné de l'aorte vers le foie","Drainer le sang du foie vers la veine cave","Amener au foie les nutriments absorbés par l'intestin","Transporter la bile vers le duodénum"],"r":2,"e":"La veine porte hépatique transporte les nutriments absorbés au niveau intestinal vers le foie qui les traite avant la circulation systémique.","s":0},{"q":"Quelles enzymes pancréatiques digèrent les protéines ?","o":["Amylase, Maltase, Sucrase","Lipase, Phospholipase, Cholestérolestérase","Trypsine, Chymotrypsine, Carboxypeptidase","Nucléases, DNase, RNase"],"r":2,"e":"Trypsine, chymotrypsine et carboxypeptidase sont les enzymes protéolytiques pancréatiques (sécrétées en zymogènes inactifs).","s":0},{"q":"Quelle association organe → rôle est juste ?","o":["Estomac : milieu très acide · foie : bile · pancréas : enzymes · intestin grêle : absorption des nutriments · gros intestin : récupération de l'eau","Estomac : bile · foie : enzymes · pancréas : milieu très acide · intestin grêle : récupération de l'eau · gros intestin : absorption des nutriments","Estomac : absorption des nutriments · foie : milieu très acide · pancréas : bile · intestin grêle : enzymes · gros intestin : récupération de l'eau","Estomac : récupération de l'eau · foie : enzymes · pancréas : bile · intestin grêle : milieu très acide · gros intestin : absorption des nutriments"],"r":0,"e":"L'estomac est très acide (pH 1,5-2) ; le foie fabrique la bile ; le pancréas apporte les enzymes de tous les nutriments ; l'intestin grêle absorbe l'essentiel des nutriments ; le gros intestin récupère l'eau et les ions restants et forme les selles avec ce qui n'a pas été digéré.","s":0},{"q":"Quelle est la fonction principale du sphincter pylorique ?","o":["Empêcher le reflux acide vers l'œsophage","Contrôler la vidange du chyme vers le duodénum","Sécréter la bile vers le duodénum, après les repas gras","Absorber l'eau du chyme, avant l'intestin"],"r":1,"e":"Le sphincter pylorique partiellement fermé permet la vidange progressive (pompe pylorique) : chaque contraction péristaltique gastrique envoie un peu de chyme vers le duodénum.","s":0},{"q":"Quel est le rôle de la gastrine ?","o":["Inhiber la sécrétion gastrique, après le repas","Stimuler la sécrétion d'HCl et de pepsinogène","Émulsifier les graisses dans le duodénum","Digérer l'amidon, en le coupant en maltose dans la bouche"],"r":1,"e":"La gastrine, libérée pendant la phase gastrique, stimule la sécrétion d'HCl et de pepsinogène par l'estomac, ainsi que la motilité gastrique.","s":0},{"q":"Le facteur intrinsèque sécrété par l'estomac est nécessaire à l'absorption :","o":["De la vitamine D3","Du fer héminique alimentaire","De la vitamine B12","Du calcium alimentaire"],"r":2,"e":"Le facteur intrinsèque (sécrété par les cellules pariétales) est indispensable à l'absorption de la vitamine B12 dans l'iléon. Son absence cause une anémie pernicieuse.","s":0},{"q":"L'émulsification des lipides est réalisée par :","o":["La pepsine","Les sels biliaires","L'amylase pancréatique","L'HCl gastrique"],"r":1,"e":"Les sels biliaires (dans la bile) émulsifient les grosses gouttelettes lipidiques en micelles → augmente la surface d'action des lipases pancréatiques.","s":0},{"q":"Quel pourcentage d'eau est absorbé dans l'intestin grêle ?","o":["50%","70%","92%","99%"],"r":2,"e":"L'intestin grêle absorbe ~92% de l'eau. Le gros intestin en absorbe 6–7%, et seulement ~1% est éliminé dans les selles.","s":0},{"q":"Les ondes péristaltiques gastriques sont caractérisées par :","o":["Une fréquence de 20 sec, faibles","Une fréquence d'environ 3/min, fortes","Aucune contraction","Des contractions circulaires uniquement"],"r":1,"e":"Les ondes péristaltiques sont des contractions plus fortes (que les ondes de mélange) survenant ~3 fois/min, propulsant le chyme vers le pylore.","s":0},{"q":"Les mouvements de masse du gros intestin surviennent :","o":["1 fois/min","1 fois/heure","3 à 4 fois/jour","Une fois par semaine"],"r":2,"e":"Les mouvements de masse (contractions puissantes propulsant le contenu colique vers le rectum) surviennent 3 à 4 fois par jour, souvent après les repas.","s":0},{"q":"Le suc pancréatique se compose de :","o":["Un composant aqueux et un composant enzymatique","De la bile uniquement, riche en sels biliaires","D'acide chlorhydrique et de pepsine","De mucus uniquement, pour protéger la muqueuse intestinale"],"r":0,"e":"Le suc pancréatique a 2 composants : aqueux (Na⁺, K⁺ ≈ LEC, neutralise l'acidité) et enzymatique (trypsine, chymotrypsine, amylase, lipase, nucléases). Le composant aqueux est riche en Na⁺ et K⁺.","s":0},{"q":"Par quelle voie les chylomicrons sont-ils absorbés ?","o":["La veine porte hépatique, directement vers le foie","Les vaisseaux lymphatiques, ou chylifères","Les capillaires sanguins de la muqueuse","Une diffusion directe vers le foie"],"r":1,"e":"Les chylomicrons sont trop volumineux pour les capillaires sanguins. Ils empruntent les lactéals (vaisseaux lymphatiques des villosités) → canal thoracique → veine sous-clavière gauche.","s":0},{"q":"Dans quel ordre se succèdent les grandes étapes de la digestion ?","o":["Ingestion → mastication → propulsion → digestion → absorption → élimination","Mastication → ingestion → absorption → propulsion → digestion → élimination","Ingestion → absorption → mastication → digestion → propulsion → élimination","Propulsion → ingestion → digestion → élimination → absorption → mastication"],"r":0,"e":"On introduit l'aliment (ingestion), on le broie (mastication), on le fait avancer (déglutition puis péristaltisme), on le dégrade mécaniquement et chimiquement, on absorbe les nutriments, puis on élimine les déchets. La propulsion comprend la déglutition et le péristaltisme, et la digestion est mécanique et chimique.","s":0},{"q":"Le GIP (Gastric Inhibitory Peptide) :","o":["Stimule la sécrétion gastrique et la vidange de l'estomac","Inhibe l'estomac et stimule la sécrétion d'insuline","Provoque la contraction de la vésicule biliaire","Stimule la sécrétion de suc pancréatique aqueux"],"r":1,"e":"Le GIP, libéré par le duodénum en réponse à du glucose et aux lipides, inhibe les sécrétions et la motilité gastriques, et stimule la libération d'insuline (effet incrétine). Il inhibe les sécrétions et la motilité gastriques.","s":0},{"q":"Quel transport est utilisé pour l'absorption du glucose dans l'entérocyte ?","o":["Une diffusion simple, des deux côtés de la cellule","SGLT1 avec Na⁺ en apical, puis GLUT2 en basolatéral","Un transport actif primaire, par une pompe à ATP","Une endocytose, puis un passage par GLUT4"],"r":1,"e":"Le glucose est absorbé via SGLT1 (cotransport actif secondaire avec Na⁺) au pôle apical, puis sort vers la circulation par GLUT2 (diffusion facilitée) au pôle basolatéral.","s":0},{"q":"Quelle est la séquence enzymatique correcte pour digérer les protéines ?","o":["Pepsine, puis enzymes pancréatiques, puis aminopeptidases","Amylase, puis lipase, puis trypsine pancréatique","Lactase, puis maltase, puis sucrase intestinale","Pepsine uniquement, active de l'estomac jusqu'au côlon terminal"],"r":0,"e":"Cascade : Pepsine (estomac, pH acide) commence → trypsine, chymotrypsine, élastase, carboxypeptidase (pancréas) continuent → aminopeptidases et dipeptidases (intestin) finissent → AA, di- et tripeptides absorbés. La pepsine agit dans l'estomac ; la trypsine, la chymotrypsine et la carboxypeptidase viennent du pancréas ; les aminopeptidases agissent dans l'intestin.","s":0},{"q":"Pourquoi la vésicule biliaire concentre-t-elle la bile ?","o":["Elle ajoute des sels biliaires, fabriqués par sa paroi","Elle réabsorbe l'eau et les ions de la bile","Elle ajoute du cholestérol à la bile","Elle dilue les enzymes du suc pancréatique"],"r":1,"e":"La vésicule biliaire réabsorbe activement l'eau et les ions, concentrant les sels biliaires 5 à 10 fois. Cela permet de stocker une grande capacité émulsifiante dans un petit volume. La bile est ainsi concentrée 5 à 10 fois.","s":0},{"q":"Le pH normal du duodénum est :","o":["1,5 – 2,0","5,6 – 8,0","7,9 – 8,5","6,8 – 7,5"],"r":1,"e":"Le duodénum a un pH 5,6-8,0 grâce à la neutralisation par le suc pancréatique riche en bicarbonates.","s":0},{"q":"Le pH normal du côlon est :","o":["6,8 – 7,5","7,2 – 7,5","7,9 – 8,5","1,5 – 2,0"],"r":2,"e":"Le côlon a un pH 7,9-8,5, le plus basique du tube digestif.","s":0},{"q":"Pendant la phase pharyngée de la déglutition :","o":["Le bol est formé dans la bouche par la langue","Le palais mou se soulève et ferme le nasopharynx","Le sphincter gastro-œsophagien s'ouvre","La progression se fait par péristaltisme dans l'œsophage"],"r":1,"e":"Phase pharyngée : palais mou ferme le nasopharynx, muscles constricteurs propulsent le bol, sphincter œsophagien supérieur se relâche.","s":0},{"q":"Le foie produit chaque jour :","o":["100 à 200 mL de bile","300 à 500 mL de bile","600 à 1000 mL de bile","1500 à 2000 mL de bile"],"r":2,"e":"Production hépatique : 600 à 1000 mL de bile par jour.","s":0},{"q":"Quelles vitamines sont stockées dans le foie ?","o":["Vitamine A","Vitamine B12","Vitamine C","Vitamine D","Vitamine E","Vitamine K"],"r":[0,1,3,4,5],"e":"Le foie stocke A, B12, D, E, K (liposolubles + B12). La vitamine C n'est pas stockée.","s":0},{"q":"Le rôle de phagocytose du foie élimine :","o":["GR âgés","GB âgés","Bactéries","Débris circulants","Hormones uniquement"],"r":[0,1,2,3],"e":"Cellules de Kupffer phagocytent GR/GB âgés, bactéries, débris circulants.","s":0},{"q":"Le sang traité par le foie repart par :","o":["L'artère hépatique → aorte abdominale basse","La veine porte → intestin grêle","Les veines hépatiques → veine cave inférieure","Le canal cholédoque → duodénum"],"r":2,"e":"Sang sortant : veines hépatiques → veine cave inférieure → cœur.","s":0},{"q":"Quel est le rôle du gros intestin ?","o":["Récupérer l'eau et les ions, puis former les selles","Sécréter la bile, pour émulsifier les graisses","Digérer les protéines, grâce à la pepsine","Absorber l'essentiel des nutriments, grâce aux villosités"],"r":0,"e":"Le gros intestin sécrète surtout du mucus (peu d'enzymes) ; il absorbe l'eau, les ions et des vitamines d'origine bactérienne, et forme les selles : eau, résidus non digérés, bactéries. Il stocke ensuite les selles avec les résidus non digérés.","s":0},{"q":"Quelles enzymes digèrent les disaccharides dans l'intestin grêle ?","o":["Pepsine","Maltase","Sucrase","Lactase","Trypsine"],"r":[1,2,3],"e":"Maltase, sucrase, lactase digèrent maltose, saccharose, lactose au niveau de la bordure en brosse.","s":0},{"q":"Comment le bol alimentaire passe-t-il de l'œsophage à l'estomac ?","o":["Par le péristaltisme, puis l'ouverture du sphincter","Par la seule gravité, sans contraction musculaire","Par une onde électrique, sans contraction","Par aspiration de l'estomac, qui se dilate"],"r":0,"e":"Phase œsophagienne de la déglutition : des ondes de contraction musculaire (péristaltisme) poussent le bol — il passe même la tête en bas — et le sphincter gastro-œsophagien s'ouvre pour le laisser entrer. Le sphincter en question est le sphincter gastro-œsophagien.","s":0},{"q":"Les hépatocytes sont :","o":["Les cellules de la vésicule biliaire","Les cellules fonctionnelles du foie","Les cellules pancréatiques","Les cellules de l'intestin"],"r":1,"e":"Hépatocytes = cellules fonctionnelles du foie (production bile, biotransformation, stockage).","s":0},{"q":"Les selles sont composées de :","o":["Uniquement des fibres végétales non digérées","D'eau, de résidus, de bactéries et de cellules","D'eau et de bactéries uniquement","De catabolites uniquement, issus du foie"],"r":1,"e":"Selles = eau + solides non digérés + micro-organismes + cellules épithéliales desquamées. Les résidus sont des solides non digérés et les cellules sont épithéliales.","s":0},{"q":"La fonction de mélange du système digestif repose sur :","o":["Des contractions segmentaires, en va-et-vient","Le péristaltisme, qui propulse le bol dans un seul sens","La déglutition, de la bouche vers l'œsophage","La mastication, par les dents et la langue"],"r":0,"e":"La propulsion réunit, elle, la déglutition et le péristaltisme. Le déplacement des aliments y est bidirectionnel.","s":0},{"q":"La fonction de sécrétion du tube digestif fournit :","o":["Du mucus, de l'eau et des enzymes","Des hormones seulement, comme la gastrine","De l'eau seulement, pour liquéfier","Du mucus seulement, pour lubrifier"],"r":0,"e":"Elle figure au cinquième rang des huit fonctions du système digestif. Le mucus lubrifie, l'eau liquéfie et les enzymes dégradent.","s":0},{"q":"Quel organe ne sécrète pas d'enzyme digestive ?","o":["Le foie","Le pancréas","L'estomac","Les glandes salivaires"],"r":0,"e":"Le foie produit la bile : ses sels biliaires émulsifient les graisses, mais elle ne contient pas d'enzyme digestive. Le pancréas (trypsine, lipase, amylase), l'estomac (pepsine) et les glandes salivaires (amylase) en sécrètent.","s":0},{"q":"Où agissent la pepsine et les enzymes pancréatiques ?","o":["Pepsine : dans l'estomac · enzymes pancréatiques : dans le duodénum","Pepsine : dans le duodénum · enzymes pancréatiques : dans l'estomac","Pepsine : dans la bouche · enzymes pancréatiques : dans le côlon","Pepsine et enzymes pancréatiques : toutes deux dans le côlon"],"r":0,"e":"La pepsine commence la digestion des protéines dans l'estomac acide ; le suc pancréatique arrive au duodénum avec du bicarbonate qui neutralise le chyme, et ses enzymes finissent la digestion des glucides, des protéines et des lipides. La pepsine est activée par l'HCl et les enzymes pancréatiques agissent en milieu neutralisé par le NaHCO₃.","s":0},{"q":"Lors de la phase céphalique de la déglutition :","o":["Le bol se forme, la langue le poussant vers l'oropharynx","Le palais mou se soulève, pour fermer le nasopharynx en haut","Le sphincter œsophagien supérieur se relâche","Le péristaltisme œsophagien démarre, vers l'estomac"],"r":0,"e":"La phase pharyngée comporte l'élévation du palais mou, la propulsion par les constricteurs et le relâchement du sphincter supérieur. La langue pousse le bol contre le palais dur.","s":0},{"q":"Lors de la phase œsophagienne de la déglutition :","o":["Le bol progresse par péristaltisme jusqu'à l'estomac","Le palais mou se ferme sur le nasopharynx","La langue pousse le bol contre le palais dur","Le pylore s'ouvre, laissant passer le bol dans le duodénum"],"r":0,"e":"C'est la troisième et dernière phase de la déglutition. Le sphincter gastro-œsophagien s'ouvre alors.","s":0},{"q":"La phase intestinale des sécrétions gastriques est déclenchée par :","o":["Un pH très acide ou des lipides dans le duodénum","La distension gastrique, par l'arrivée du bol alimentaire","Le goût et l'odorat, avant le repas","La gastrine, libérée par l'antre"],"r":0,"e":"La phase gastrique repose sur la distension et les chémorécepteurs, qui libèrent la gastrine. Le seuil est un pH inférieur à 2 ; l'inhibition passe par la sécrétine, la CCK et le GIP.","s":0},{"q":"Lors du remplissage gastrique :","o":["Les plis s'atténuent et le volume augmente","Les plis s'accentuent, pour retenir les aliments","Le volume reste constant, la paroi étant rigide","Le pylore s'ouvre aussitôt"],"r":0,"e":"Le mélange se fait ensuite par des ondes de mélange d'environ 20 secondes et des ondes péristaltiques plus fortes.","s":0},{"q":"Quelle est l'unité fonctionnelle du rein ?","o":["Le glomérule","Le néphron","Le TCP","Le calice"],"r":1,"e":"Le néphron est l'unité fonctionnelle : corpuscule rénal (glomérule + capsule de Bowman) + TCP + anse de Henle + TCD + canal collecteur.","s":1},{"q":"Combien de néphrons compte chaque rein environ ?","o":["~10 000","~100 000","~1 million","~10 millions"],"r":2,"e":"Chaque rein contient environ 1 million de néphrons. Leur nombre ne peut pas augmenter (perte = irréversible).","s":1},{"q":"Quel est le poids approximatif d'un rein ?","o":["~50 g","~140 g","~500 g","~1 kg"],"r":1,"e":"Chaque rein pèse ~140 g. Pourtant, les reins traitent 180 L d'eau et 1,5 kg de sel par jour.","s":1},{"q":"Le cortex rénal est :","o":["La zone interne, avec les pyramides","La zone externe, avec les glomérules","Le bassinet, qui collecte l'urine des calices","L'uretère, à la sortie du hile"],"r":1,"e":"Le cortex (externe) contient les glomérules et la majorité des tubules. La médulla (interne) contient les pyramides de Malpighi. Il contient aussi la majorité des tubules.","s":1},{"q":"Quel est le volume d'urine produit par jour environ ?","o":["100 ml","500 ml","1,5 L","5 L"],"r":2,"e":"Volume normal d'urine ≈ 1,5 L/jour. Cela représente seulement ~1% du filtrat (180 L/jour) — le reste est réabsorbé.","s":1},{"q":"L'érythropoïétine est sécrétée par :","o":["Le foie","La rate","Les reins","La moelle osseuse"],"r":2,"e":"Les reins sécrètent l'érythropoïétine (EPO), hormone qui stimule la production de globules rouges dans la moelle osseuse.","s":1},{"q":"Quels sont les 3 étapes de production de l'urine ?","o":["Filtration, réabsorption, sécrétion","Sécrétion, digestion, absorption","Inspiration, expiration, perfusion","Excrétion, défécation, miction"],"r":0,"e":"Les 3 étapes : 1) Filtration glomérulaire, 2) Réabsorption tubulaire, 3) Sécrétion tubulaire.","s":1},{"q":"L'urine est transportée du rein à la vessie par :","o":["L'urètre","Les uretères","Les calices","Le bassinet"],"r":1,"e":"Les uretères (2) transportent l'urine des reins vers la vessie. L'urètre (1) la conduit ensuite hors du corps.","s":1},{"q":"Le détrusor est :","o":["Une enzyme","Le muscle de la vessie","Une partie du néphron","Une hormone"],"r":1,"e":"Le détrusor est le muscle lisse de la paroi vésicale. Sa contraction (parasympathique) permet la miction.","s":1},{"q":"Quel est le débit de filtration glomérulaire (TFG) normal ?","o":["Environ 50 ml/min","Environ 125 ml/min","Environ 300 ml/min","Environ 5 ml/min"],"r":1,"e":"TFG normal ≈ 125 ml/min (~180 L/jour). La clairance de la créatinine est utilisée comme estimation clinique. Cela représente environ 180 L par jour.","s":1},{"q":"Quelles substances NE PASSENT PAS la barrière de filtration glomérulaire ?","o":["L'eau et le glucose du plasma","Les ions et l'urée dissous","Les cellules sanguines et les protéines","La créatinine, déchet du métabolisme musculaire"],"r":2,"e":"La barrière retient les cellules sanguines (volumineuses) et les protéines plasmatiques (charge négative + taille). La protéinurie signe une atteinte de cette barrière. Ce sont les protéines plasmatiques.","s":1},{"q":"Combien de couches forment la barrière de filtration glomérulaire ?","o":["1, l'endothélium du capillaire","2, l'endothélium et la membrane basale glomérulaire","3, endothélium, membrane basale et podocytes","5, avec la capsule et le mésangium"],"r":2,"e":"3 couches : 1) endothélium fenestré, 2) membrane basale glomérulaire (charges négatives, repousse les protéines), 3) podocytes (avec leurs pédicelles).","s":1},{"q":"Où se fait la filtration du sang dans le néphron ?","o":["Dans le corpuscule rénal, vers la capsule de Bowman","Dans l'anse de Henle, au fond de la médulla","Dans les pyramides de Malpighi, en médulla","Dans le canal collecteur, tout en fin de néphron"],"r":0,"e":"La filtration glomérulaire a lieu dans le corpuscule rénal : la pression pousse le plasma du glomérule à travers la membrane de filtration vers la capsule de Bowman (le filtrat). L'anse de Henle concentre, les pyramides forment la médulla, le canal collecteur ajuste l'eau.","s":1},{"q":"Quel est le rôle de l'ADH ?","o":["↑ sécrétion de Na⁺ → urine salée","Insère des aquaporines → ↑ réabsorption d'eau","Stimule la rénine → ↑ angiotensine II","Diminue la filtration → ↓ volume d'urine produit"],"r":1,"e":"L'ADH (neurohypophyse) augmente la perméabilité du TCD/canal collecteur à l'eau via l'insertion d'aquaporines (AQP2) → urine concentrée. Elles sont insérées au TCD et au canal collecteur.","s":1},{"q":"Dans quelle situation la rénine est-elle libérée ?","o":["En cas d'hypertension artérielle sévère","En cas d'hyperhydratation","En cas d'hypotension ou de baisse du Na⁺","En cas d'excès de potassium"],"r":2,"e":"La rénine est libérée par l'appareil juxtaglomérulaire en réponse à : 1) baisse de PA (barorécepteurs), 2) baisse de NaCl (macula densa), 3) stimulation sympathique β1.","s":1},{"q":"L'aldostérone agit principalement en :","o":["Diminuant la réabsorption de Na⁺ et d'eau","Réabsorbant Na⁺ et eau et sécrétant K⁺","Stimulant la libération de rénine","Inhibant l'angiotensine II circulante"],"r":1,"e":"L'aldostérone (TCD/canal collecteur) ↑ réabsorption Na⁺ et eau, ↑ sécrétion K⁺ et H⁺. Effecteur final du SRAA. Elle augmente aussi la sécrétion de H⁺.","s":1},{"q":"Que signifie la glycosurie ?","o":["Une bonne santé métabolique","Un diabète non contrôlé","Une déshydratation, avec une urine concentrée","Une insuffisance rénale terminale"],"r":1,"e":"Glycosurie = glucose dans l'urine. Normalement tout le glucose est réabsorbé au TCP. Si glycémie > seuil rénal (~1,8 g/L), l'excès apparaît dans l'urine. Signe classique de diabète mal équilibré. La glycémie dépasse le seuil rénal, d'environ 1,8 g/L.","s":1},{"q":"Quel est l'effet de l'ANP ?","o":["Il augmente la pression artérielle et la volémie","Il s'oppose au SRAA et abaisse la pression","Il active la libération de rénine","Il stimule l'aldostérone et l'ADH"],"r":1,"e":"L'ANP (sécrété par les cellules auriculaires en réponse à une distension) antagonise le SRAA : ↑ TFG, ↓ réabsorption Na⁺, inhibe rénine/aldostérone/ADH → ↓ PA. Il augmente le TFG et réduit la réabsorption de Na⁺.","s":1},{"q":"Quelle est la formule du calcul de la quantité excrétée ?","o":["E = F + R","E = F − R + S","E = F × R / S","E = R − F"],"r":1,"e":"Excrétion (E) = Filtration (F) − Réabsorption (R) + Sécrétion (S). Formule fondamentale de la physiologie rénale.","s":1},{"q":"Le mécanisme à contre-courant fonctionne grâce à :","o":["L'aldostérone seule, par la réabsorption de sodium","Des anses de Henle et vasa recta à contre-sens","La filtration glomérulaire, à débit constant","La vessie, qui concentre l'urine stockée"],"r":1,"e":"Le multiplicateur à contre-courant : anses de Henle (descendante perméable à H₂O, ascendante perméable au NaCl) + vasa recta créent un gradient osmotique croissant dans la médulla (300 → 1200 mOsm/kg). Le gradient osmotique va de 300 à 1200 mOsm.","s":1},{"q":"La protéinurie peut signer :","o":["Une bonne hydratation de l'organisme","Une atteinte de la barrière de filtration","Une infection urinaire uniquement","Une déshydratation, avec une urine très concentrée"],"r":1,"e":"La protéinurie indique le passage anormal de protéines (souvent albumine) à travers la barrière glomérulaire. Néphropathie diabétique, glomérulonéphrites… (peut être physiologique après un effort intense). C'est le cas d'une néphropathie glomérulaire.","s":1},{"q":"L'urine concentrée est produite quand :","o":["Hyperhydratation → ↓ ADH","Déshydratation → ↑ ADH","Excès de Na⁺ alimentaire → ↓ ADH et diurèse","Insuffisance rénale terminale → ↓ ADH"],"r":1,"e":"Urine concentrée = ADH élevée. Déclenché par déshydratation (osmolalité ↑) ou volémie ↓ → osmorécepteurs hypothalamiques → ↑ ADH. L'osmolalité plasmatique est alors augmentée.","s":1},{"q":"L'urine diluée est produite quand :","o":["L'ADH est absente ou faible","Une déshydratation, avec une ADH élevée","Des vomissements répétés","Une sudation intense, à l'effort"],"r":0,"e":"Sans ADH, le TCD/canal collecteur sont imperméables à l'eau → l'eau reste dans le filtrat → urine diluée et abondante. C'est le cas lors d'une hyperhydratation.","s":1},{"q":"Le néphron juxtamédullaire est caractérisé par :","o":["Une anse de Henle courte, restant dans le cortex","Une longue anse de Henle plongeant dans la médulla","L'absence de glomérule, avec un tubule seul et isolé","Une localisation dans la paroi vésicale"],"r":1,"e":"Les néphrons juxtamédullaires (~20%) ont des anses de Henle longues qui plongent dans la médulla. Ils sont essentiels au mécanisme à contre-courant et donc à la concentration de l'urine. Il joue un rôle clé dans la concentration de l'urine.","s":1},{"q":"Quel est le calcul de la pression de filtration nette ?","o":["PCG + PHC + POC = 100 mmHg","PCG − PHC − POC = 10 mmHg","PCG × PHC / POC = 27 mmHg","PHC + POC − PCG = −10 mmHg"],"r":1,"e":"Pression nette = PCG (55) − PHC (15) − POC (30) = 10 mmHg. PCG = pression capillaire glom., PHC = pression hydrostatique capsulaire, POC = pression oncotique. Soit 55 − 15 − 30.","s":1},{"q":"Quelle est la particularité de la branche descendante de l'anse de Henle ?","o":["Imperméable à l'eau, perméable au NaCl","Très perméable à l'eau, peu aux solutés","Imperméable à tout, eau et solutés","Réabsorbant le glucose, par SGLT2"],"r":1,"e":"Branche descendante : très perméable à l'eau, peu aux solutés → l'eau quitte → filtrat se concentre. Ascendante : imperméable à l'eau, perméable au NaCl → filtrat se dilue. Le filtrat s'y concentre.","s":1},{"q":"Le segment large de l'anse ascendante utilise :","o":["Un cotransporteur Na⁺/K⁺/2Cl⁻","Une simple diffusion, à travers 2 canaux passifs","Aucun transporteur, la paroi étant étanche","L'osmose seule, entraînant l'eau"],"r":0,"e":"Le cotransporteur NKCC2 (Na⁺/K⁺/2Cl⁻) du segment large ascendant réabsorbe ~25% du Na⁺ filtré. Cible des diurétiques de l'anse (furosémide).","s":1},{"q":"L'aquaporine 2 (AQP2) est :","o":["Constitutive du TCD, sans régulation","Insérée au canal collecteur sous l'effet de l'ADH","Située dans le glomérule, contre les podocytes et l'endothélium","Présente dans l'estomac, pour le suc gastrique"],"r":1,"e":"L'ADH se fixe sur ses récepteurs V2 → ↑ AMPc → translocation des vésicules contenant AQP2 vers la membrane apicale → réabsorption d'eau. Sans ADH, AQP2 retourne en intracellulaire. Elle s'insère dans la membrane apicale.","s":1},{"q":"L'angiotensine II augmente la réabsorption de Na⁺ au TCP via :","o":["L'antiporteur Na⁺/H⁺, ou NHE3","Une pompe Cl⁻/HCO₃⁻ apicale","L'aquaporine 4, ou AQP4","Aucun mécanisme direct"],"r":0,"e":"L'Ang II stimule l'antiporteur Na⁺/H⁺ (NHE3) au TCP, augmentant la réabsorption de Na⁺ (et donc d'eau). Action directe sur le tubule, en plus de la stimulation de l'aldostérone.","s":1},{"q":"Le mécanisme tubuloglomérulaire est :","o":["Un réglage sans rétroaction, à débit fixe","Une rétroaction de la macula densa sur le TFG","Une action de l'ADH sur le canal collecteur","Une activité de l'aldostérone sur le TCD"],"r":1,"e":"Rétroaction tubulo-glomérulaire : la macula densa (TCD) détecte le NaCl. Si NaCl ↑ (TFG trop élevé), libération d'adénosine → vasoconstriction de l'artériole afférente → ↓ TFG. Elle ajuste le TFG selon le NaCl tubulaire.","s":1},{"q":"Quel est le trajet du sang autour du glomérule ?","o":["Artériole afférente → glomérule → artériole efférente → capillaires péritubulaires","Artériole efférente → glomérule → artériole afférente → capillaires péritubulaires","Veine rénale → glomérule → artère rénale","Capillaires péritubulaires → glomérule → artériole afférente"],"r":0,"e":"L'artériole afférente amène le sang au glomérule, l'efférente l'en fait sortir vers les capillaires péritubulaires (et les vasa recta des néphrons juxtamédullaires), qui récupèrent ce que le tubule réabsorbe.","s":1},{"q":"Que détecte la macula densa, au contact de l'artériole afférente ?","o":["La concentration en NaCl du filtrat au début du TCD","La pression dans la vessie, au remplissage","La glycémie du sang qui traverse l'artériole afférente","Le taux d'O2 du sang artériel"],"r":0,"e":"Une baisse du NaCl au début du TCD est l'un des trois déclencheurs de la rénine, avec la baisse de pression dans l'artériole afférente et la stimulation sympathique ; c'est aussi la base du rétrocontrôle tubulo-glomérulaire. Si elle baisse, la rénine est libérée.","s":1},{"q":"Que passe à travers la membrane de filtration glomérulaire ?","o":["Eau","Petits ions","Glucose","Urée","Cellules sanguines","Albumine"],"r":[0,1,2,3],"e":"Passent : eau, petits solutés (ions, glucose, urée, créatinine, AA). Ne passent PAS : cellules sanguines et protéines plasmatiques.","s":1},{"q":"Quelles sont les 6 fonctions du système urinaire ?","o":["La filtration du sang","La régulation du volume sanguin","La régulation des ions","La régulation du pH","La synthèse des globules rouges","La régulation de la vitamine D","La production de la bile","La sécrétion de l'insuline"],"r":[0,1,2,3,4,5],"e":"Filtrer le sang, réguler le volume sanguin, la concentration des ions et le pH, sécréter l'érythropoïétine et réguler la vitamine D (donc le calcium). La bile vient du foie, l'insuline du pancréas. La synthèse des globules rouges passe par l'érythropoïétine.","s":1},{"q":"L'anse de Henle descendante est :","o":["Très perméable à l'eau, peu aux solutés","Imperméable à l'eau, perméable au NaCl","Perméable au glucose","Sécrète l'ADH"],"r":0,"e":"Branche descendante : très perméable à l'eau (sort par osmose), peu aux solutés → filtrat se concentre.","s":1},{"q":"L'anse de Henle ascendante est caractérisée par :","o":["Imperméable à l'eau, réabsorbant le NaCl","Très perméable à l'eau, peu aux solutés","Sécrétant des H⁺, pour l'urine","Réabsorbant le glucose, en totalité"],"r":0,"e":"Branche ascendante : imperméable à l'eau, pompe Na+/K+/2Cl- réabsorbe ~15% du filtrat → filtrat se dilue. Elle utilise la pompe Na⁺/K⁺/2Cl⁻.","s":1},{"q":"Sur un schéma du rein, dans quel ordre l'urine traverse-t-elle les zones, de la périphérie vers le hile ?","o":["Cortex → médulla → calices mineurs puis majeurs → bassinet → uretère","Médulla → cortex → bassinet → calices mineurs puis majeurs → uretère","Bassinet → calices → pyramides → cortex → uretère","Cortex → bassinet → pyramides → calices → uretère"],"r":0,"e":"Le cortex, en périphérie, contient les glomérules ; la médulla est faite des pyramides de Malpighi ; les calices drainent l'urine vers le bassinet, qui se continue par l'uretère au niveau du hile. Le cortex contient les glomérules et la médulla les pyramides de Malpighi.","s":1},{"q":"Les néphrons juxtamédullaires :","o":["Représentent environ 80 % des néphrons, en cortex externe","Ont des anses courtes, restant dans le cortex","Représentent environ 20 % et ont des anses longues","Sont uniquement dans le cortex superficiel"],"r":2,"e":"Juxtamédullaires (~20%) ont anses longues qui pénètrent dans la médulla, essentiels pour le mécanisme à contre-courant. Ces anses longues sont clés pour la concentration urinaire.","s":1},{"q":"Le réflexe de miction est déclenché par :","o":["La contraction volontaire du sphincter externe, strié","La distension de la vessie, par un arc réflexe","La libération d'ADH par la post-hypophyse","La chute du débit de filtration glomérulaire"],"r":1,"e":"Vers 200-300 mL, les mécanorécepteurs de la paroi vésicale sont étirés ; l'influx gagne la moelle sacrée S2-S4, d'où part la commande parasympathique qui contracte le détrusor et relâche le sphincter interne. Le sphincter externe, strié, reste sous contrôle volontaire. Cet arc réflexe est parasympathique, de S2 à S4.","s":1},{"q":"Le trigone vésical est délimité par :","o":["Les deux orifices urétéraux et l'orifice urétral interne","Les deux sphincters de l'urètre, interne et externe","Le col vésical et le pelvis rénal","Les deux artères vésicales, supérieure et inférieure"],"r":0,"e":"Le trigone est le triangle lisse du plancher vésical dont les trois sommets sont les deux abouchements des uretères et l'orifice interne de l'urètre. Sa muqueuse, peu plissée, est une zone de départ fréquente des infections et des tumeurs.","s":1},{"q":"Le sphincter externe de l'urètre est :","o":["Lisse, involontaire","Strié, volontaire","Cardiaque","Absent"],"r":1,"e":"Sphincter externe = strié, volontaire (contrôle conscient). Sphincter interne = lisse, involontaire.","s":1},{"q":"Les déchets éliminés par sécrétion tubulaire incluent :","o":["H+","K+","Glucose","NH4+","Créatinine","Médicaments"],"r":[0,1,3,4,5],"e":"Sécrétion : H+, K+, NH4+, urée, créatinine, médicaments. Le glucose est totalement réabsorbé, pas sécrété.","s":1},{"q":"Chaque jour, les reins traitent environ :","o":["180 L d'eau et 1,5 kg de sel","18 L d'eau et 150 g de sel","1,5 L d'eau et 180 g de sel, soit l'urine du jour","500 L d'eau et 5 kg de sel"],"r":0,"e":"Ce contraste entre le volume traité et la masse de l'organe illustre son efficacité. Chaque rein ne pèse pourtant qu'environ 140 g.","s":1},{"q":"La régulation du pH par le rein passe par :","o":["La sécrétion de quantités variables d'ions H⁺","La seule sécrétion de bicarbonates","La filtration des protéines plasmatiques acides","La sécrétion d'érythropoïétine"],"r":0,"e":"Les six fonctions du système urinaire comprennent aussi filtration, régulation du volume et des solutés, synthèse des globules rouges et vitamine D. Elle se fait vers le liquide extracellulaire.","s":1},{"q":"La régulation de la synthèse de vitamine D par le rein permet :","o":["Le contrôle des taux de calcium dans le sang","La régulation du sodium plasmatique","La synthèse des globules rouges","La régulation du pH, par les ions H⁺ urinaires"],"r":0,"e":"L'érythropoïétine régule, elle, la synthèse des globules rouges dans la moelle osseuse.","s":1},{"q":"La vascularisation rénale suit l'ordre :","o":["Artère rénale, segmentaires, interlobaires puis arquées","Artère rénale, glomérule, puis artériole afférente","Artériole efférente, glomérule, puis artériole afférente","Artère rénale, artères arquées, segmentaires puis interlobaires"],"r":0,"e":"Les vasa recta accompagnent les néphrons juxtamédullaires. Suivent les interlobulaires, l'artériole afférente, le glomérule, l'artériole efférente et les capillaires péritubulaires.","s":1},{"q":"Les néphrons corticaux représentent environ :","o":["20 % des néphrons","50 %","80 %","95 %"],"r":2,"e":"Les néphrons juxtamédullaires, environ 20 %, ont de très longues anses et jouent le rôle clé dans la concentration de l'urine.","s":1},{"q":"Dans quel ordre le filtrat parcourt-il le néphron ?","o":["Corpuscule rénal → TCP → anse de Henle → TCD → canal collecteur","Anse de Henle → corpuscule rénal → TCD → TCP → canal collecteur","TCP → TCD → corpuscule rénal → anse de Henle → canal collecteur","Canal collecteur → TCD → anse de Henle → TCP → corpuscule rénal"],"r":0,"e":"Du corpuscule rénal, le filtrat passe dans le tubule contourné proximal, l'anse de Henle (branche descendante puis ascendante), le tubule contourné distal puis le canal collecteur, vers le bassinet. Le corpuscule comprend la capsule de Bowman.","s":1},{"q":"La pression capillaire glomérulaire est d'environ :","o":["55 mmHg, qui force la filtration","15 mmHg, qui s'oppose à la filtration","30 mmHg, pression oncotique du plasma","10 mmHg, la pression nette de filtration glomérulaire"],"r":0,"e":"La pression hydrostatique capsulaire (15 mmHg) et la pression oncotique (30 mmHg) s'y opposent, donnant une filtration nette de 10 mmHg.","s":1},{"q":"Le tubule contourné proximal réabsorbe environ :","o":["65 % du filtrat, dont tout le glucose","15 % du filtrat, surtout du sodium","90 % du filtrat, sauf le glucose","30 % du filtrat, dont la moitié de l'eau filtrée"],"r":0,"e":"Il est perméable à l'eau, donc isosmotique, et possède une bordure en brosse. Il réabsorbe aussi environ 50 % du sodium et de l'eau.","s":1},{"q":"Quel est le pH normal du sang artériel ?","o":["7,00 – 7,15","7,35 – 7,45","7,55 – 7,65","7,80 – 8,00"],"r":1,"e":"pH artériel normal = 7,35–7,45 (≈ 7,40). En dessous = acidémie ; au-dessus = alcalémie.","s":2},{"q":"Le pH se calcule par :","o":["log [OH⁻]","−log [H⁺]","[H⁺] × 10","[H⁺]/[OH⁻]"],"r":1,"e":"pH = −log [H⁺]. Une variation de 1 unité pH = variation × 10 de [H⁺].","s":2},{"q":"Une acidose correspond à :","o":["pH > 7,45","pH < 7,35","pH = 7,40","pH = 7,00"],"r":1,"e":"Acidose = pH < 7,35. Alcalose = pH > 7,45. Variation de 1 pH = ×10 [H⁺].","s":2},{"q":"Quels sont les 6 électrolytes clés ?","o":["Na⁺, K⁺, Cl⁻, HCO₃⁻, Ca²⁺ et PO₄³⁻","C, H, N, O, P et S, les éléments du vivant","Fe, Cu, Zn, Mg, Mn et Se","Les vitamines A, B, C, D, E et K"],"r":0,"e":"Les 6 électrolytes principaux : sodium, potassium, chlorure, bicarbonate, calcium, phosphate.","s":2},{"q":"Le fluide intracellulaire représente environ :","o":["20 % de l'eau totale, dans le plasma","60 % de l'eau totale, soit environ 25 L","100 % de l'eau totale","5 % de l'eau totale"],"r":1,"e":"Le LIC ≈ 60% de l'eau corporelle totale (~25 L chez l'adulte). Le LEC = 1/3 (plasma 20% + interstitiel 80%).","s":2},{"q":"L'apport hydrique quotidien est environ :","o":["500 ml","1 000 ml","2 500 ml","10 000 ml"],"r":2,"e":"Apport hydrique ≈ 2 500 ml/j : boissons (1 600) + aliments (700) + eau métabolique (200).","s":2},{"q":"Le pH cytoplasmique cellulaire est :","o":["Environ 7,40, comme le sang","Environ 6,8, un peu plus acide que le sang","Environ 8,5, nettement plus basique que le sang","Environ 5,0, comme l'estomac"],"r":1,"e":"Le pH intracellulaire (~6,8) est légèrement plus acide que le pH sanguin (~7,40). Production constante de CO₂ et acides métaboliques.","s":2},{"q":"Un acide est une substance qui :","o":["Capte les ions H⁺ en solution","Libère des ions H⁺ en solution","Libère des ions OH⁻","Ne réagit pas avec l'eau"],"r":1,"e":"Acide (Brønsted) = donneur de H⁺. Base = accepteur de H⁺. HCl → H⁺ + Cl⁻.","s":2},{"q":"Le HCl est un :","o":["Un acide faible, partiellement dissocié","Un acide fort, entièrement dissocié","Une base forte, captant les H⁺","Un tampon, de pH stable"],"r":1,"e":"HCl est un acide fort entièrement dissocié en H⁺ + Cl⁻. C'est l'acide gastrique.","s":2},{"q":"Une acidose métabolique est caractérisée par :","o":["pH > 7,45 et HCO₃⁻ ↑","pH &lt; 7,35 et HCO₃⁻ ↓","pH &lt; 7,35 et pCO₂ ↑","pH > 7,45 et pCO₂ ↓, par hyperventilation"],"r":1,"e":"Acidose métabolique = pH < 7,35 et HCO₃⁻ ↓. Causes : acidose lactique, cétoacidose diabétique, insuffisance rénale, diarrhée. Le HCO₃⁻ est alors inférieur à 22 mEq/L.","s":2},{"q":"Une acidose respiratoire est caractérisée par :","o":["pH < 7,35 et pCO₂ ↑ (>45 mmHg)","pH > 7,45 et pCO₂ ↓","pH < 7,35 et HCO₃⁻ ↓","pH normal"],"r":0,"e":"Acidose respiratoire = pH < 7,35 et pCO₂ > 45 mmHg. Causes : hypoventilation (BPCO, emphysème, dépression respiratoire).","s":2},{"q":"Une alcalose respiratoire est caractérisée par :","o":["pH &lt; 7,35 et pCO₂ ↑, par hypoventilation","pH > 7,45 et pCO₂ ↓","pH > 7,45 et HCO₃⁻ ↑","pH normal et pCO₂ normale"],"r":1,"e":"Alcalose respiratoire = hyperventilation → pCO₂ ↓ < 35 mmHg → pH > 7,45. Causes : anxiété, altitude, AVC. La pCO₂ est alors inférieure à 35 mmHg.","s":2},{"q":"Une alcalose métabolique est caractérisée par :","o":["pH > 7,45 et HCO₃⁻ ↑","pH > 7,45 et pCO₂ ↓","pH < 7,35 et HCO₃⁻ ↓","Aucun"],"r":0,"e":"Alcalose métabolique = pH > 7,45 et HCO₃⁻ ↑. Causes : vomissements répétés (perte d'HCl), ingestion d'alcalins, hypokaliémie.","s":2},{"q":"Quelle situation provoque une alcalose respiratoire ?","o":["Une hypoventilation, par sédation","Une hyperventilation, par anxiété","Des vomissements répétés","Une diarrhée sévère, avec perte de bicarbonates"],"r":1,"e":"L'hyperventilation élimine trop de CO₂ → pCO₂ ↓ → pH ↑. Causes typiques : crise d'angoisse, altitude, AVC. L'altitude en est une autre cause.","s":2},{"q":"Quel est le tampon principal du plasma ?","o":["Le tampon protéique, –COOH/–NH₂","Le tampon hémoglobine, Hb/HHb","Le tampon bicarbonate, HCO₃⁻/H₂CO₃","Le tampon phosphate, HPO₄²⁻"],"r":2,"e":"Le couple HCO₃⁻/H₂CO₃ est le tampon principal extracellulaire (plasma + liquide interstitiel). Régulé par poumons (CO₂) et reins (HCO₃⁻).","s":2},{"q":"Le tampon le plus abondant (3/4 de la capacité tampon totale) est :","o":["Le tampon bicarbonate, plasmatique","Le tampon phosphate, intracellulaire","Le tampon protéique, dont l'hémoglobine","Le tampon ammoniac, dans les tubules rénaux"],"r":2,"e":"Les protéines (groupements –COOH/–NH₂ ionisables) représentent ~75% de la capacité tampon totale, en intra et extracellulaire. Il agit en intra et en extracellulaire.","s":2},{"q":"Le tampon bicarbonate en cas d'acidose réagit ainsi :","o":["HCO₃⁻ + H⁺ → H₂CO₃ → CO₂ + H₂O","H₂CO₃ → H⁺ + HCO₃⁻, libérant des protons","Na⁺ + Cl⁻ → NaCl, éliminé par le rein","OH⁻ + H⁺ → H₂O, sans gaz produit"],"r":0,"e":"En acidose, HCO₃⁻ capte H⁺ → H₂CO₃ → CO₂ + H₂O. Le CO₂ est éliminé par les poumons (réponse rapide). Le CO₂ est éliminé par les poumons.","s":2},{"q":"Quel est le rôle du tampon hémoglobine ?","o":["Le tampon plasmatique principal","Un tampon des globules rouges, qui capte les H⁺","Un tampon du foie, qui neutralise les acides biliaires","Un tampon urinaire, dans les tubules"],"r":1,"e":"Hb capte H⁺ libéré par la dissociation H₂CO₃ → H⁺ + HCO₃⁻. ~70-80% du CO₂ tissulaire est transporté sous forme HCO₃⁻ via l'anhydrase carbonique érythrocytaire.","s":2},{"q":"Le tampon ammoniac (NH₃/NH₄⁺) agit principalement :","o":["Dans le plasma, en circulation sanguine","Dans les globules rouges","Dans les tubules rénaux distaux","Dans le foie, par le cycle de l'urée"],"r":2,"e":"NH₃ + H⁺ → NH₄⁺ excrété dans l'urine. Permet d'éliminer H⁺ tout en préservant le HCO₃⁻ plasmatique.","s":2},{"q":"Le tampon phosphate agit principalement :","o":["Dans le plasma uniquement, en circulation","Dans les cellules et les tubules rénaux","Dans les voies digestives, du duodénum au côlon","Dans la bile, stockée dans la vésicule"],"r":1,"e":"Le tampon phosphate (HPO₄²⁻/H₂PO₄⁻) est principalement intracellulaire et tubulaire rénal. Concentration trop faible dans le LEC pour y être important.","s":2},{"q":"Pendant un effort intense (anaérobie), l'acide produit est :","o":["Acide carbonique","Acide lactique","Acide phosphorique","Acide sulfurique"],"r":1,"e":"Glycolyse anaérobie : glucose → pyruvate → lactate (acide lactique). Source de H⁺ qui doit être tamponnée.","s":2},{"q":"Le métabolisme aérobie produit comme acide :","o":["L'acide lactique, issu du glucose","L'acide carbonique, issu du CO₂ et d'eau","L'acide sulfurique, issu des protéines","L'acide phosphorique, issu de l'ATP"],"r":1,"e":"Le CO₂ produit par le métabolisme aérobie + H₂O → H₂CO₃ → H⁺ + HCO₃⁻. C'est la source principale (normale) de H⁺.","s":2},{"q":"L'oxydation des AA soufrés (méthionine, cystéine) produit :","o":["De l'acide acétique, par fermentation","De l'acide sulfurique, ou H₂SO₄","De l'acide lactique, par glycolyse","Du CO₂, par décarboxylation"],"r":1,"e":"L'oxydation des AA soufrés produit H₂SO₄, acide non volatil qui doit être éliminé par les reins (sous forme de SO₄²⁻ urinaire).","s":2},{"q":"Une respiration de Kussmaul est typique de :","o":["Alcalose métabolique","Alcalose respiratoire","Acidose métabolique sévère","Acidose respiratoire"],"r":2,"e":"Respiration de Kussmaul = hyperventilation rapide et profonde, compensation respiratoire d'une acidose métabolique sévère (ex : acidocétose diabétique).","s":2},{"q":"L'équation de Henderson-Hasselbalch pour le système bicarbonate est :","o":["pH = pKa + log ([HCO₃⁻] / [H₂CO₃])","pH = − log ([H⁺] × [OH⁻])","pH = log ([H⁺] / [OH⁻])","pH = pKa − log ([HCO₃⁻] × [CO₂])"],"r":0,"e":"Henderson-Hasselbalch : pH = pKa + log([HCO₃⁻]/[H₂CO₃]). pKa = 6,1. [HCO₃⁻] / [CO₂ × 0,03] doit ≈ 20 pour pH = 7,40.","s":2},{"q":"Le rapport HCO₃⁻ / H₂CO₃ normal est :","o":["1/1, à pH neutre de 7","20/1, pour un pH de 7,40","100/1, en alcalose","1/20, en acidose sévère"],"r":1,"e":"Pour un pH = 7,40, [HCO₃⁻]/[H₂CO₃] = 20/1 (24 mmol/L / 1,2 mmol/L). Tout déséquilibre de ce ratio entraîne acidose/alcalose.","s":2},{"q":"L'anhydrase carbonique catalyse :","o":["HCl ⇌ H⁺ + Cl⁻, dans l'estomac","CO₂ + H₂O ⇌ H₂CO₃ ⇌ H⁺ + HCO₃⁻","Na⁺ + Cl⁻ → NaCl, dans le tubule","Hb + O₂ → HbO₂, dans les globules rouges"],"r":1,"e":"Anhydrase carbonique catalyse l'hydratation rapide du CO₂ en H₂CO₃ (et réaction inverse). Présente dans érythrocytes, cellules tubulaires rénales, estomac. Cible des inhibiteurs (acétazolamide).","s":2},{"q":"Le trou anionique (anion gap) est calculé par :","o":["[Na⁺] − ([Cl⁻] + [HCO₃⁻]), soit environ 12","[K⁺] + [Cl⁻] − [Na⁺], soit environ 140 mEq/L","([HCO₃⁻] − [pCO₂]) × 2, soit environ 4","pH × pCO₂, soit environ 300"],"r":0,"e":"Anion gap = [Na⁺] − ([Cl⁻] + [HCO₃⁻]) ≈ 8–12 mEq/L. Augmenté dans acidoses métaboliques avec accumulation d'acides organiques (lactate, cétones, salicylates).","s":2},{"q":"Une acidose métabolique avec anion gap élevé suggère :","o":["Une diarrhée, par perte de HCO₃⁻","Une acidocétose ou une acidose lactique","Des vomissements, avec perte d'acide","Une hyperventilation anxieuse"],"r":1,"e":"Anion gap élevé → accumulation d'acides organiques non-mesurés : MUDPILES (Méthanol, Urémie, Diabétique cétoacidose, Propylène/Paraldéhyde, Iron/Isoniazide, Lactate, Éthylène glycol, Salicylates). Une intoxication au méthanol ou à l'éthylène glycol en est une autre cause.","s":2},{"q":"Une compensation respiratoire d'acidose métabolique se traduit par :","o":["↑ ventilation → ↓ pCO₂, type Kussmaul","↓ ventilation → ↑ pCO₂, type apnée","↑ HCO₃⁻ rénal seul → pH normal","Aucune compensation → pH stable"],"r":0,"e":"Acidose métabolique → chémorécepteurs périphériques détectent ↓ pH → ↑ ventilation → pCO₂ ↓ → ramène le pH vers la normale (compensation rapide, partielle).","s":2},{"q":"Complète : « Une acidose (pH &lt; 7,35) ______ le système nerveux central, jusqu'au ______ ; une alcalose (pH &gt; 7,45) le rend ______, avec un risque de ______. »","o":["déprime · coma · hyperexcitable · tétanie","excite · réveil · somnolent · paralysie flasque","déprime · réveil · calme · hypotonie","excite · convulsions · déprimé · coma"],"r":0,"e":"Acidose = dépression du SNC : céphalées, somnolence, confusion, jusqu'au coma. Alcalose = hyperexcitabilité du SNC et du SNP : tremblements, tétanie, convulsions — l'alcalose fait baisser le calcium ionisé.","s":2},{"q":"Une diarrhée sévère entraîne plutôt :","o":["Une acidose métabolique, par perte de bicarbonates","Une alcalose métabolique, par perte d'acide","Une alcalose respiratoire, par hyperventilation","Une acidose respiratoire, par une hypoventilation réflexe"],"r":0,"e":"Le cours range la diarrhée sévère parmi les causes d'acidose métabolique (HCO₃⁻ ↓) : les sécrétions intestinales perdues sont riches en bicarbonates. L'alcalose métabolique vient au contraire des vomissements.","s":2},{"q":"pH < 6,85 ou pH > 7,95 entraîne :","o":["Une légère somnolence","Aucun effet","La mort cellulaire","Une accélération métabolique"],"r":2,"e":"Au-delà de ces bornes, mort cellulaire car les protéines/canaux perdent leur structure 3D.","s":2},{"q":"Une variation de 1 unité de pH correspond à :","o":["×2 [H+]","×5 [H+]","×10 [H+]","×100 [H+]"],"r":2,"e":"Échelle logarithmique : 1 unité pH = facteur 10 sur [H+].","s":2},{"q":"Les sources de H+ issues du métabolisme incluent :","o":["Le métabolisme aérobie, via le CO₂","Le métabolisme anaérobie, via le lactate","L'oxydation des acides gras, via les cétones","L'oxydation des acides aminés soufrés","L'hydrolyse des phosphoprotéines","L'excrétion rénale des H⁺ dans l'urine"],"r":[0,1,2,3,4],"e":"Toutes ces voies génèrent des H+. Source principale en conditions normales : CO2 de la respiration aérobie. L'excrétion rénale élimine les H⁺, elle n'en produit pas : c'est un mécanisme de compensation, pas une source.","s":2},{"q":"Les mécanismes tampons de l'organisme sont principalement :","o":["Anti-alcalosiques","Anti-acidosiques","Pro-acidosiques","Neutres"],"r":1,"e":"L'organisme produit beaucoup plus d'acides → mécanismes tampons principalement anti-acidosiques.","s":2},{"q":"Des vomissements répétés entraînent plutôt :","o":["Une alcalose métabolique, par perte d'HCl gastrique","Une acidose métabolique, par perte de bicarbonates","Une acidose respiratoire, par une hypoventilation réflexe","Aucune modification du pH, par compensation"],"r":0,"e":"En vomissant, on perd l'acide chlorhydrique de l'estomac : il reste trop de bases, HCO₃⁻ ↑ et pH &gt; 7,45 — alcalose métabolique, avec hyperexcitabilité et tétanie possibles.","s":2},{"q":"Comparée aux tampons chimiques, la compensation RÉNALE d'un déséquilibre acido-basique est :","o":["Immédiate, mais très limitée en capacité","Lente, mais la plus puissante des défenses","Impossible en cas d'acidose métabolique","Identique à la compensation respiratoire"],"r":1,"e":"Trois lignes de défense se succèdent : les tampons chimiques (secondes, capacité limitée), la compensation respiratoire (minutes), puis le rein (heures à jours). Seul le rein excrète définitivement les H⁺ fixes et régénère le HCO₃⁻ ; c'est donc le mécanisme le plus lent mais le plus puissant. Elle prend des heures à des jours et est la seule à éliminer réellement les H⁺.","s":2},{"q":"Quel pourcentage du CO2 tissulaire est transporté en HCO3- ?","o":["10–20%","30–40%","50–60%","70–80%"],"r":3,"e":"70-80% du CO2 transporté sous forme HCO3- dans le plasma, via l'anhydrase carbonique.","s":2},{"q":"L'acidose métabolique est caractérisée par :","o":["pCO2 > 45 mmHg et pH &lt; 7,35","HCO3- &lt; 22 mEq/L et pH &lt; 7,35","HCO3- > 26 mEq/L et pH > 7,45","pH > 7,45 et pCO2 &lt; 35 mmHg"],"r":1,"e":"Acidose métabolique : ↓ HCO3- (<22 mEq/L) et pH < 7,35. Causes : acidose lactique, cétoacidose, IR, diarrhée.","s":2},{"q":"La respiration de Kussmaul (rapide et profonde) est associée à :","o":["L'alcalose respiratoire","L'acidose métabolique","L'alcalose métabolique","L'acidose respiratoire"],"r":1,"e":"Respiration de Kussmaul = compensation de l'acidose métabolique : ↑ fréquence et amplitude pour expulser le CO2.","s":2},{"q":"La tétanie en cas d'alcalose s'explique par :","o":["Une hyperkaliémie, par sortie du potassium cellulaire","Une hypocalcémie, le calcium se fixant sur l'os","Une hypoglycémie, par excès d'insuline","Une hyperthermie, par la fièvre"],"r":1,"e":"Alcalose → dépôt de Ca2+ dans les os → hypocalcémie → canaux Na+ non bloqués → hyper-excitabilité → tétanie.","s":2},{"q":"Le fluide extracellulaire se compose :","o":["Du plasma et du fluide interstitiel","Du seul plasma sanguin","Du seul liquide interstitiel, entre les cellules","Du liquide intracellulaire"],"r":0,"e":"Il représente environ un tiers de l'eau totale, contre 60 % pour le fluide intracellulaire, soit environ 25 L. Le plasma en représente environ 20 %.","s":2},{"q":"L'apport hydrique quotidien de 2 500 mL se répartit en :","o":["1 600 mL de boissons, 700 d'aliments et 200 d'eau métabolique","2 500 mL de boissons, sans autre apport notable","1 000 mL de boissons et 1 500 mL apportés par les aliments","500 mL de boissons, le reste par les aliments et l'air"],"r":0,"e":"Les pertes se répartissent en 1 500 mL d'urine, 400 par la peau, 300 par l'air expiré, 100 par les selles et 100 par la sueur.","s":2},{"q":"La régulation du sodium et du potassium repose sur :","o":["L'aldostérone et l'angiotensine II","L'ADH seule, par la réabsorption d'eau libre","Le pH sanguin seul","Le calcium plasmatique, par la PTH"],"r":0,"e":"Les six électrolytes clés sont Na⁺, K⁺, Cl⁻, HCO₃⁻, Ca²⁺ et PO₄³⁻. L'aldostérone augmente la réabsorption de sodium et l'excrétion de potassium.","s":2},{"q":"Une acidose entraîne :","o":["Une dépression du système nerveux central","Une hyper-excitabilité nerveuse","Une tétanie, par hypocalcémie","Des convulsions, par excitation neuronale diffuse"],"r":0,"e":"L'alcalose, au-dessus de 7,45, provoque au contraire une hyper-excitabilité du SNC.","s":2},{"q":"L'hydrolyse des phosphoprotéines produit :","o":["De l'acide phosphorique","De l'acide sulfurique","De l'acide lactique","Des corps cétoniques"],"r":0,"e":"L'oxydation des acides aminés soufrés produit de l'acide sulfurique et celle des acides gras des corps cétoniques.","s":2},{"q":"L'acidose respiratoire se caractérise par :","o":["Une pCO₂ supérieure à 45 mmHg, par hypoventilation","Un HCO₃⁻ inférieur à 22 mEq/L, par diarrhée","Une pCO₂ inférieure à 35 mmHg, par hyperventilation","Un HCO₃⁻ élevé, au-dessus de 26 mEq/L, par vomissements"],"r":0,"e":"Elle entraîne une dépression du SNC, voire un coma, avec une respiration déprimée. Ses causes sont l'hypoventilation, l'emphysème, l'œdème pulmonaire ou l'obstruction.","s":2},{"q":"L'acidose métabolique se caractérise par :","o":["Un HCO₃⁻ inférieur à 22 mEq/L, par acide lactique","Une pCO₂ élevée, au-dessus de 45 mmHg, par hypoventilation","Une pCO₂ basse, sous 35 mmHg","Un HCO₃⁻ élevé, au-dessus de 26 mEq/L"],"r":0,"e":"Elle provoque une respiration de Kussmaul, rapide et profonde, et des problèmes cardiovasculaires. Les corps cétoniques, l'insuffisance rénale ou une diarrhée sévère en sont d'autres causes.","s":2},{"q":"L'alcalose respiratoire se manifeste par :","o":["Des picotements, des tremblements et une confusion","Une dépression du SNC, avec somnolence","Une respiration de Kussmaul, ample, rapide et profonde","Un coma, par dépression respiratoire"],"r":0,"e":"Elle résulte d'une hyperventilation, par anxiété sévère, altitude ou AVC, avec une pCO₂ inférieure à 35 mmHg. Une crise épileptique est possible.","s":2},{"q":"Combien de chromosomes contient une cellule somatique humaine ?","o":["23, en un seul exemplaire","46, soit 23 paires","92, après réplication","44, sans chromosomes sexuels"],"r":1,"e":"Cellule somatique = 2n = 46 chromosomes (22 paires d'autosomes + 1 paire sexuelle XX/XY). Gamètes haploïdes n=23.","s":3},{"q":"Combien de chromosomes contient un gamète humain ?","o":["23, haploïde","46, diploïde","92, tétraploïde","44, sans X ni Y"],"r":0,"e":"Les gamètes (spermatozoïde, ovule) sont haploïdes : n = 23 chromosomes (issus de la méiose).","s":3},{"q":"Le caryotype féminin est :","o":["46, XY","46, XX","47, XXY","45, X"],"r":1,"e":"Caryotype féminin normal = 46, XX. Caryotype masculin = 46, XY. Anomalies : Klinefelter (47, XXY), Turner (45, X).","s":3},{"q":"Combien de jours dure le cycle menstruel typique ?","o":["~14 jours","~21 jours","~28 jours","~35 jours"],"r":2,"e":"Cycle menstruel typique : ~28 jours (variable de 21 à 35 jours).","s":3},{"q":"Quand a lieu l'ovulation lors d'un cycle de 28 jours ?","o":["Jour 7, sous l'effet de la FSH","Jour 14, juste après le pic de LH","Jour 21, en phase lutéale","Jour 1, avec les règles"],"r":1,"e":"Ovulation ~24h après le pic de LH, généralement vers le jour 14 du cycle.","s":3},{"q":"Où a lieu la spermatogenèse ?","o":["Les cellules de Leydig","Les tubes séminifères des testicules","L'épididyme, où les spermatozoïdes mûrissent","La prostate et les vésicules séminales"],"r":1,"e":"Spermatogenèse = tubes séminifères des testicules. Maturation finale dans l'épididyme.","s":3},{"q":"Quelles cellules produisent la testostérone ?","o":["Les cellules de Sertoli, sous FSH","Les cellules de Leydig, sous LH","Les cellules de Kupffer, dans le foie","Les cellules bêta, du pancréas"],"r":1,"e":"Cellules de Leydig = cellules interstitielles testiculaires, sous contrôle de la LH, produisent la testostérone. Ce sont des cellules interstitielles.","s":3},{"q":"Quel est le rôle des cellules de Sertoli ?","o":["Produire la testostérone, sous l'effet de la LH","Soutenir la spermatogenèse et sécréter l'inhibine","Fabriquer le liquide séminal, avec le fructose","Sécréter le mucus de l'urètre"],"r":1,"e":"Cellules de Sertoli (sous FSH) : nourrissent et soutiennent les cellules germinales, sécrètent l'inhibine (rétroaction négative sur FSH). Elles agissent sous FSH.","s":3},{"q":"L'âge moyen de la puberté chez la fille est :","o":["6–8 ans","11–13 ans","16–18 ans","20–22 ans"],"r":1,"e":"Puberté féminine : 11–13 ans (↑ œstrogènes + progestérone). Ménarche entre 11 et 16 ans typiquement.","s":3},{"q":"Quel est le rôle de la FSH chez l'homme ?","o":["Stimuler la testostérone par les cellules de Leydig","Stimuler la spermatogenèse par les Sertoli","Inhiber la GnRH hypothalamique","Réguler l'érection, par le NO"],"r":1,"e":"FSH ♂ : agit sur les cellules de Sertoli → spermatogenèse. LH ♂ : agit sur cellules de Leydig → testostérone.","s":3},{"q":"L'hormone produite par le corps jaune après l'ovulation est :","o":["Des œstrogènes seuls, sans progestérone","La progestérone, avec un peu d'œstrogènes","La FSH et la LH, d'origine hypophysaire","L'inhibine seule, contre la FSH"],"r":1,"e":"Corps jaune (corpus luteum) sécrète principalement de la progestérone (et œstrogènes) pour préparer l'endomètre à une éventuelle nidation.","s":3},{"q":"Si la fécondation n'a pas lieu, que devient le corps jaune ?","o":["Il persiste → progestérone maintenue","Il dégénère → ↓ progestérone → règles","Il devient un nouveau follicule","Il libère un autre ovocyte"],"r":1,"e":"Sans fécondation, le corps jaune dégénère vers J24-26 → corpus albicans → ↓ progestérone et œstrogènes → desquamation endométriale = règles. Il devient le corpus albicans.","s":3},{"q":"Où se déroule la fécondation ?","o":["Dans la cavité de l'utérus","Dans l'ovaire, à la surface du follicule rompu","Dans l'ampoule de la trompe de Fallope","Dans le vagin, près du col"],"r":2,"e":"Fécondation dans l'ampoule de la trompe de Fallope. L'œuf migre ensuite vers l'utérus où il s'implante (~J6-7). L'ampoule correspond au tiers externe de la trompe.","s":3},{"q":"Quelle est la durée de vie d'un spermatozoïde dans les voies féminines ?","o":["1 heure","12 heures","3 à 5 jours","1 mois"],"r":2,"e":"Spermatozoïde survit 3–5 jours dans les voies féminines. Ovocyte fécondable ~24h. Fenêtre de fertilité : ~6 jours autour de l'ovulation.","s":3},{"q":"L'hCG est sécrétée par :","o":["L'hypophyse, comme la LH","Le trophoblaste, dès l'implantation","L'ovaire, par le corps jaune","L'hypothalamus, comme la GnRH hypophysiotrope"],"r":1,"e":"hCG = gonadotrophine chorionique humaine, sécrétée par le trophoblaste/placenta dès l'implantation. Maintient le corps jaune jusqu'à ~10-12 SA. Détectée par les tests de grossesse.","s":3},{"q":"Quel est le rôle principal de la testostérone ?","o":["Réguler la glycémie, comme l'insuline et le glucagon","Les caractères masculins et la spermatogenèse","Produire la bile, avec le foie","La seule croissance osseuse"],"r":1,"e":"Testostérone : caractères sexuels secondaires masculins, soutient la spermatogenèse, libido, masse musculaire (anabolisant), érythropoïèse, voix grave, pilosité, métabolisme. Elle agit aussi sur la libido, la masse musculaire et l'érythropoïèse.","s":3},{"q":"Le pic de LH déclenche :","o":["La menstruation, par chute hormonale","L'ovulation, par rupture du follicule","La fécondation, dans la trompe","La nidation, dans l'endomètre"],"r":1,"e":"Pic de LH (déclenché par rétroaction positive des œstrogènes) → rupture du follicule de De Graaf → ovulation (~24h après le pic). Il s'agit du follicule de De Graaf.","s":3},{"q":"Quel est le pic d'hormone qui déclenche le pic de LH ?","o":["La progestérone, en phase lutéale","Les œstrogènes, par rétroaction positive","L'inhibine, par rétroaction négative","La FSH, en début de cycle"],"r":1,"e":"En fin de phase folliculaire, les œstrogènes deviennent très élevés → bascule de rétroaction négative vers positive → pic de GnRH → pic de LH (et FSH). Cela se produit en fin de phase folliculaire.","s":3},{"q":"La phase folliculaire dure :","o":["Toujours 14 jours fixes, quel que soit le cycle","Une durée variable, selon la longueur du cycle","Toujours 21 jours, en moyenne","Un mois, du premier au dernier jour"],"r":1,"e":"Phase folliculaire = variable. C'est elle qui détermine la longueur du cycle. Phase lutéale = constante 14 jours. Elle varie de 6 à 16 jours environ.","s":3},{"q":"La phase lutéale dure :","o":["Une durée variable, selon le cycle","Une durée constante de 14 jours","21 jours, comme la phase folliculaire","7 jours, avec les règles"],"r":1,"e":"Phase lutéale = TOUJOURS 14 jours (durée de vie du corps jaune en l'absence de grossesse). C'est la phase folliculaire qui varie.","s":3},{"q":"L'inhibine est sécrétée par :","o":["L'hypothalamus, au même titre que la GnRH","Les cellules de Sertoli et de la granulosa","Les cellules de Leydig, sous LH","L'hypophyse, comme la FSH"],"r":1,"e":"Inhibine : ♂ Sertoli, ♀ granulosa → rétroaction négative spécifique sur la FSH (sans agir sur la LH). Sertoli chez l'homme, granulosa chez la femme.","s":3},{"q":"Le follicule de De Graaf correspond au :","o":["Un follicule primordial, au repos","Un follicule mature, prêt à ovuler","Un corps jaune, formé après l'ovulation","Un corps albicans, cicatriciel"],"r":1,"e":"Follicule de De Graaf = follicule mature (tertiaire/antral), volumineux, prêt à se rompre lors de l'ovulation.","s":3},{"q":"L'ovogenèse commence :","o":["À la puberté, avec les premiers cycles","Avant la naissance, en vie fœtale","Après la ménopause, à l'arrêt des cycles","À 20 ans, avec la maturité ovarienne complète"],"r":1,"e":"L'ovogenèse débute pendant la vie fœtale, méiose I bloquée en prophase I jusqu'à la puberté. Stock fixe d'ovocytes à la naissance (~400 000). La méiose I y reste bloquée en prophase I jusqu'à la puberté.","s":3},{"q":"Quand la méiose II est-elle complétée chez la femme ?","o":["Avant la naissance, pendant la vie fœtale","À la puberté, au premier cycle","Au moment du pic de LH","Après l'entrée du spermatozoïde"],"r":3,"e":"Méiose II est bloquée en métaphase II et n'est complétée qu'APRÈS la pénétration du spermatozoïde dans l'ovocyte II. Elle est donc liée à la fécondation.","s":3},{"q":"Le clivage de l'angiotensinogène par la rénine produit :","o":["L'aldostérone, sécrétée par la surrénale","L'angiotensine I, ensuite convertie par l'ECA","Une hormone hypothalamique, la CRH","La calcitonine, par la thyroïde"],"r":1,"e":"Note : ce concept appartient au Cours 2. Pour le système reproducteur, retenir que les axes hormonaux sont précisément régulés par cascades enzymatiques similaires. L'ECA la convertit en angiotensine II.","s":3},{"q":"Le 1er corps polaire est libéré :","o":["Avant la naissance, sous l'effet de la FSH","Au moment du pic de LH, juste avant l'ovulation","Après la fécondation, avec le second globule polaire","Pendant la nidation, dans l'endomètre"],"r":1,"e":"Pic de LH → achèvement de la méiose I → libération du 1er globule polaire et formation de l'ovocyte II. Méiose II reprendra qu'à la fécondation. Il marque l'achèvement de la méiose I.","s":3},{"q":"L'implantation a lieu vers :","o":["Le jour même de la fécondation, dans la trompe","Vers le 6e ou 7e jour après la fécondation","Vers le 14e jour, avec l'ovulation","Vers le 28e jour, avec les règles"],"r":1,"e":"Après fécondation, l'œuf se divise en cheminant dans la trompe → blastocyste → implantation dans l'endomètre vers J6-7 post-fécondation. L'œuf est alors au stade de blastocyste.","s":3},{"q":"Le placenta prend le relais du corps jaune vers :","o":["1 SA","10–12 SA","20 SA","À l'accouchement"],"r":1,"e":"L'hCG maintient le corps jaune jusqu'à ~10-12 SA. Ensuite, le placenta produit suffisamment de progestérone pour maintenir la grossesse.","s":3},{"q":"La barrière hémato-testiculaire est formée par :","o":["Les cellules de Leydig, entre les tubes","Des jonctions serrées entre cellules de Sertoli","La tunique albuginée, enveloppe fibreuse du testicule","L'endothélium des capillaires testiculaires"],"r":1,"e":"La barrière hémato-testiculaire (jonctions serrées entre cellules de Sertoli) protège les spermatozoïdes (cellules haploïdes étrangères au système immunitaire) d'une réaction auto-immune.","s":3},{"q":"L'aromatase :","o":["Convertit le glucose en glycogène, dans le foie et le muscle","Convertit les androgènes en œstrogènes","Détruit les œstrogènes, dans le foie","Active la testostérone, en DHT"],"r":1,"e":"Aromatase : enzyme qui convertit androgènes (testostérone, androstènedione) → œstrogènes (E2, E1). Présente dans granulosa, tissu adipeux, etc. Cible des inhibiteurs (cancer du sein hormonodépendant). Elle est présente dans la granulosa et le tissu adipeux.","s":3},{"q":"Le spermatozoïde se compose de :","o":["La tête, avec l'ADN","La partie médiane, riche en mitochondries","La queue, faite de microtubules","Le vitellus, réserve nutritive","Le flagelle, pour la locomotion"],"r":[0,1,2,4],"e":"Tête (ADN), partie médiane (mitochondries = ATP), queue/flagelle (locomotion). Le vitellus est dans l'ovule.","s":3},{"q":"Le vitellus est :","o":["Une enzyme du sperme, qui digère la zone pellucide","La réserve nutritive de l'ovule, jusqu'à l'implantation","Une hormone de l'ovaire, sécrétée en phase lutéale","Un type de spermatozoïde, immobile"],"r":1,"e":"Vitellus = réserves nutritives de l'ovule, nourrit l'embryon jusqu'à l'implantation.","s":3},{"q":"La spermatogenèse a lieu dans :","o":["L'épididyme, au-dessus du testicule","Les tubules séminifères des testicules","La prostate, sous la vessie","Les vésicules séminales"],"r":1,"e":"Spermatogenèse dans les tubules séminifères des testicules.","s":3},{"q":"Les cellules de Sertoli :","o":["Nourrissent les cellules germinales","Sécrètent l'inhibine","Produisent la testostérone","Contrôlent les cellules germinales"],"r":[0,1,3],"e":"Sertoli : nourricières + sécrètent inhibine (rétro FSH). La testostérone vient des cellules de Leydig.","s":3},{"q":"Les cellules de Leydig produisent :","o":["L'inhibine","La testostérone","La LH","Les spermatozoïdes"],"r":1,"e":"Cellules de Leydig (interstitielles) = production de testostérone, stimulées par LH.","s":3},{"q":"L'ovocyte II est bloqué en méiose II en :","o":["Prophase II, avant toute condensation des chromosomes","Métaphase II, jusqu'à la fécondation","Anaphase II, à la séparation","Télophase II, en fin de division"],"r":1,"e":"Ovocyte II bloqué en métaphase II ; débloqué par la pénétration du spermatozoïde → ovule + 2e corps polaire.","s":3},{"q":"FSH agit sur :","o":["Cellules de Leydig → testostérone","Cellules de Sertoli → spermatogenèse","Hypothalamus","Glandes surrénales"],"r":1,"e":"FSH stimule cellules de Sertoli → développement des spermatozoïdes (synergie avec testostérone).","s":3},{"q":"La phase lutéale du cycle féminin dure :","o":["Variable selon la longueur du cycle","6 à 16 jours","Constamment 14 jours","21 jours"],"r":2,"e":"Phase lutéale = constante 14 jours. Seule la phase folliculaire varie (6-16 jours).","s":3},{"q":"Le déclencheur de l'ovulation est :","o":["Un pic de FSH","Un pic de LH","Une chute de progestérone","Un pic d'œstrogènes seul"],"r":1,"e":"Ovulation : pic de LH (déclenché par rétroaction positive des œstrogènes en fin de phase folliculaire).","s":3},{"q":"Les vésicules séminales contribuent au sperme à hauteur de :","o":["10%","30%","60%","90%"],"r":2,"e":"Vésicules séminales = 60% du sperme, contenu visqueux et alcalin (fructose, prostaglandines).","s":3},{"q":"La prostate sécrète :","o":["De l'acide citrique","Des enzymes protéolytiques","Du zinc, qui stabilise l'ADN","Du fructose, source d'énergie","Un plasma antibiotique"],"r":[0,1,2,4],"e":"Prostate (~30% sperme, pH 6,5) : acide citrique, enzymes décoagulantes, zinc, plasma antibiotique. Fructose = vésicules séminales.","s":3},{"q":"Le pH final du sperme est :","o":["Acide (~5,5)","Légèrement acide (~6,5)","Alcalin (~7,2-7,7)","Neutre (~7,0)"],"r":2,"e":"pH final ~7,2-7,7 (alcalin) malgré l'acidité de la prostate, grâce au volume et à l'alcalinité des vésicules séminales.","s":3},{"q":"La partie médiane du spermatozoïde est :","o":["Riche en mitochondries, source d'énergie","Porteuse de l'ADN, dans le noyau","Faite de microtubules de locomotion","Riche en vitellus, réserve de l'ovule entier"],"r":0,"e":"La tête contient l'ADN sous une coiffe riche en enzymes, et la queue les microtubules de locomotion.","s":3},{"q":"Le vitellus de l'ovule :","o":["Nourrit l'embryon jusqu'à l'implantation","Assure la mobilité de l'ovule","Contient l'ADN maternel","Produit les hormones du début de grossesse"],"r":0,"e":"C'est la réserve nutritive qui explique la grande taille de l'ovule.","s":3},{"q":"La spermiogenèse correspond à l'étape :","o":["Des spermatides vers les spermatozoïdes","De la spermatogonie vers le spermatocyte I","De la méiose I","De la méiose II"],"r":0,"e":"Elle achève la spermatogenèse dans les tubules séminifères.","s":3},{"q":"L'ovocyte I est bloqué :","o":["En prophase I, de la vie fœtale à la puberté","En métaphase II, jusqu'à la fécondation","En anaphase I, à la séparation des paires","En télophase, juste avant la division du cytoplasme"],"r":0,"e":"L'ovocyte II est ensuite bloqué en métaphase II, débloqué par la pénétration du spermatozoïde.","s":3},{"q":"Le mécanisme hormonal de la puberté associe :","o":["Une baisse de sensibilité à la rétroaction négative","Une seule hausse de la sécrétion de GnRH","Une seule hausse de la sensibilité des gonades à la LH","Aucun changement de sensibilité hormonale"],"r":0,"e":"Il en résulte une augmentation de LH et FSH, la croissance des gonades et la gamétogenèse. Elle concerne l'hypothalamus et l'hypophyse, et s'accompagne d'une hausse de sensibilité des gonades à la FSH et à la LH.","s":3},{"q":"Parmi les facteurs influençant la puberté, le cours cite comme facteur majeur :","o":["La nutrition","La génétique","L'environnement","Le stress psychologique"],"r":0,"e":"Les quatre facteurs cités sont la génétique, l'environnement, le stress psychologique et la nutrition.","s":3},{"q":"La ménarche survient :","o":["Entre 11 et 13 ans, en moyenne","Entre 8 et 10 ans, en moyenne","Entre 14 et 16 ans, en moyenne","Après 16 ans, à la fin de la croissance"],"r":0,"e":"La puberté masculine survient entre 12 et 14 ans avec l'augmentation de la testostérone. La puberté s'achève vers 16 ans.","s":3},{"q":"Parmi les sept effets de la testostérone figure :","o":["Une hausse de l'érythropoïèse, d'environ 20 %","Une baisse du métabolisme de base, de 10 %","Une baisse de la masse musculaire","Une peau plus fine, moins sébacée"],"r":0,"e":"S'y ajoutent croissance capillaire, peau plus rugueuse, sécrétion sébacée, hypertrophie du larynx, métabolisme de base et synthèse protéique.","s":3},{"q":"Quelle est l'unité contractile du muscle squelettique ?","o":["La myofibrille","Le sarcomère","La fibre musculaire","Le fascicule"],"r":1,"e":"Le sarcomère est l'unité contractile (entre 2 stries Z), composé de filaments épais (myosine) et fins (actine).","s":4},{"q":"VO₂max correspond à :","o":["Le volume d'O₂ inhalé au repos","La consommation maximale d'O₂ à l'effort","La pression d'O₂ dans le sang artériel","La saturation de l'hémoglobine en O₂, au doigt"],"r":1,"e":"VO₂max = consommation maximale d'oxygène utilisable. Exprimé en ml/kg/min. Meilleur marqueur de l'aptitude aérobie.","s":4},{"q":"Le débit cardiaque au repos est environ :","o":["1 L/min","5 L/min","20 L/min","50 L/min"],"r":1,"e":"Débit cardiaque au repos ≈ 5 L/min (FC × VES = 70 × 70 ml). À l'exercice maximal : 25–30 L/min.","s":4},{"q":"Combien de temps dure le système ATP-PCr (phosphagène) ?","o":["Environ 10 secondes, en effort explosif","Environ 30 minutes, en endurance","Environ 1 heure, en effort modéré","Sans limite, tant que l'oxygène arrive"],"r":0,"e":"Le système ATP-phosphocréatine fournit de l'énergie ~10 secondes (sprints, haltérophilie). Régénère rapidement l'ATP sans O₂.","s":4},{"q":"L'eau dans l'organisme représente quel pourcentage du poids ?","o":["20%","60%","80%","100%"],"r":1,"e":"L'eau corporelle ≈ 60% du poids (variable selon âge, sexe, masse grasse). Très importante pour la thermorégulation à l'effort.","s":4},{"q":"La principale méthode de thermorégulation à l'exercice est :","o":["Les frissons thermiques","La vasoconstriction cutanée","La vasodilatation cutanée et la sudation","La hausse du métabolisme, par production de chaleur"],"r":2,"e":"Effort = production massive de chaleur. Évacuation par : vasodilatation cutanée + sudation (évaporation = principal mécanisme). L'évaporation de la sueur en est le principal mécanisme.","s":4},{"q":"L'hydratation pré-exercice recommandée est :","o":["100 ml juste avant l'effort","600 à 800 ml, 10 à 15 min avant l'effort","3 L bus d'un coup, la veille au soir","Aucune eau, pour éviter les crampes"],"r":1,"e":"Préhydratation : 600–800 ml d'eau 10–15 min avant l'effort. Pendant : petites quantités toutes les 10–15 min.","s":4},{"q":"Pour la population générale, la répartition glucides/lipides/protéines est :","o":["20/60/20, riche en lipides","50/30/15, le reste en fibres","10/10/80, riche en protéines","100 % de protéines, sans glucides ni graisses"],"r":1,"e":"Population générale : ~50% glucides, ~30% lipides, ~15% protéines. Privilégier glucides complexes et lipides insaturés.","s":4},{"q":"Le sportif doit avoir une alimentation :","o":["Identique à celle d'un sédentaire","Plus riche en glucides, pour le glycogène","Sans glucides, pour brûler les graisses","Riche en alcool, pour l'apport calorique rapide"],"r":1,"e":"Sportif : 60–70% glucides (glycogène musculaire), ~12% protéines. Vigilance fer et calcium. Les glucides doivent représenter 60 à 70 % des apports.","s":4},{"q":"Quelle est la principale source d'énergie immédiate (1ères secondes) ?","o":["La glycolyse anaérobie","La phosphocréatine, ou ATP-PCr","La phosphorylation oxydative","La β-oxydation des acides gras, via l'ATP"],"r":1,"e":"Le système ATP-PCr (phosphagène) fournit l'énergie pendant les ~10 premières secondes : la créatine phosphate régénère rapidement l'ATP.","s":4},{"q":"La glycolyse anaérobie produit comme déchet :","o":["De l'eau et du CO₂, éliminés par les poumons","De l'acide lactique, ou lactate","De l'ammoniac, par désamination","Des corps cétoniques, issus des lipides"],"r":1,"e":"Glycolyse anaérobie : glucose → pyruvate → lactate. Alimente les efforts intenses 30 sec à 2 min. Le lactate participe à la fatigue.","s":4},{"q":"Pour un effort modéré prolongé (>30 min), la principale filière est :","o":["La phosphocréatine, pour les efforts explosifs","La glycolyse anaérobie, avec du lactate","Le métabolisme aérobie, glucides puis lipides","La protéolyse des muscles actifs"],"r":2,"e":"Effort prolongé modéré : métabolisme aérobie. Oxydation glucides (glycogène) puis recours croissant aux lipides (β-oxydation).","s":4},{"q":"L'augmentation du débit cardiaque à l'effort est due à :","o":["FC seule","VES seul","Augmentation de FC ET de VES","Diminution des résistances"],"r":2,"e":"Q = FC × VES. À l'effort : passage de 5 → 25-30 L/min par ↑ FC (jusqu'à FCmax ≈ 220-âge) et ↑ VES (jusqu'à plateau).","s":4},{"q":"L'EPOC (dette d'oxygène) est :","o":["Un manque permanent d'O₂ dans les tissus","Un excès de consommation d'O₂ après l'effort","Un déficit en hémoglobine, après l'effort","L'O₂ stocké dans la myoglobine des fibres rouges"],"r":1,"e":"EPOC : consommation d'O₂ qui reste élevée après l'effort. Sert à : régénérer phosphagènes, métaboliser le lactate, restaurer myoglobine, thermorégulation. Il sert à rétablir l'homéostasie.","s":4},{"q":"Le flux sanguin à l'effort est redirigé :","o":["Vers le tube digestif, après le repas","Vers les muscles actifs et la peau","Vers le cerveau seul, protégé","Vers aucun organe, le débit total baissant"],"r":1,"e":"Effort : vasodilatation musculaire + vasoconstriction splanchnique → muscles actifs reçoivent jusqu'à 80% du débit. Peau aussi pour thermorégulation. Cela se fait au détriment des viscères.","s":4},{"q":"Pendant l'exercice, la ventilation peut atteindre :","o":["6 L/min seulement","20 L/min","100 L/min","1000 L/min"],"r":2,"e":"Ventilation au repos = 6 L/min. À l'effort intense : jusqu'à 100 L/min (×15-20). Augmentation par ↑ fréquence + ↑ volume courant (athlète favorise VT).","s":4},{"q":"La FC max théorique se calcule par :","o":["220 − âge","100 − âge","Âge × 2","Toujours 200"],"r":0,"e":"Formule classique : FCmax ≈ 220 − âge (estimation, ±10-15 bpm de variation interindividuelle).","s":4},{"q":"Quel hormone augmente fortement à l'effort pour mobiliser glycogène et lipides ?","o":["L'insuline, par le pancréas","L'adrénaline et la noradrénaline","L'ADH, par la posthypophyse","L'aldostérone, par la corticosurrénale"],"r":1,"e":"Catécholamines (adré, noradré) ↑ à l'effort : ↑ FC, ↑ contractilité, glycogénolyse (mobilise glycogène), lipolyse (mobilise lipides). Insuline ↓.","s":4},{"q":"L'entraînement aérobie au long cours entraîne au repos :","o":["Une FC augmentée, en tachycardie","Une FC basse et un VES augmenté","Un VES diminué, par fatigue cardiaque","Une HTA, par épaississement des parois artérielles"],"r":1,"e":"Entraînement endurance : bradycardie de repos (<60 bpm chez l'athlète) car le VES augmente. Le débit cardiaque de repos reste constant. C'est la bradycardie d'entraînement.","s":4},{"q":"Une adaptation typique de l'entraînement en endurance est :","o":["Une hypertrophie massive, avec hausse du diamètre musculaire","Plus de mitochondries, de capillaires et de myoglobine","Une baisse du VO₂max, par fatigue chronique","Une conversion des fibres I en IIb"],"r":1,"e":"Aérobie : ↑ nombre/taille des mitochondries, densité capillaire musculaire, myoglobine, enzymes oxydatives, VO₂max. Le diamètre musculaire change peu. Les enzymes oxydatives augmentent aussi.","s":4},{"q":"VO₂max chez un jeune adulte moyen est :","o":["10 ml/kg/min","~50 ml/kg/min","100 ml/kg/min","Variable inconnu"],"r":1,"e":"VO₂max moyen jeune adulte ≈ 50 ml/kg/min. Athlète d'endurance : 70-90 ml/kg/min. Sédentaire : 30-40.","s":4},{"q":"L'effet presseur de l'exercice est :","o":["Une baisse de la PA, par vasodilatation","Une hausse de la PA, surtout de la systolique","Une PA stable, quelle que soit l'intensité","Une hypotension, par fuite plasmatique"],"r":1,"e":"Effet presseur : ↑ PA systolique à l'exercice (+50-100 mmHg). Plus marqué pour les membres supérieurs (masse musculaire moindre, vasoconstriction). PA diastolique stable ou ↓. Elle est plus marquée pour les membres supérieurs.","s":4},{"q":"La triade musculaire est :","o":["Trois sarcomères alignés","Un tubule T et deux citernes du réticulum","Trois fibres musculaires voisines","L'actine, la myosine et la tropomyosine"],"r":1,"e":"Triade = jonction tripartite : 1 tubule T (invagination membranaire) + 2 citernes terminales du réticulum sarcoplasmique. Permet le couplage excitation-contraction.","s":4},{"q":"Quel ion déclenche la contraction musculaire ?","o":["Le Na⁺, entrant par les canaux rapides","Le K⁺, sortant au repos","Le Ca²⁺, libéré par le réticulum","Le Mg²⁺, fixé à l'ATP"],"r":2,"e":"Le PA → tubule T → ouverture canaux Ca²⁺ du RS → libération Ca²⁺ dans le cytosol → fixation sur troponine → glissement des filaments → contraction.","s":4},{"q":"Le seuil anaérobie (lactique) correspond à :","o":["L'absence totale d'oxygène dans le muscle actif","L'intensité où le lactate s'accumule dans le sang","Le VO₂max, atteint en fin d'effort maximal","Le niveau de repos, avant l'effort"],"r":1,"e":"Seuil lactique : intensité où la production de lactate dépasse sa clairance → accumulation. Survient à ~50-70% du VO₂max chez le sédentaire, plus haut chez l'athlète. Marqueur clé d'endurance. Il s'accumule plus vite qu'il n'est éliminé.","s":4},{"q":"Le quotient respiratoire (QR) au repos est environ :","o":["Environ 0,2, en jeûne","Environ 0,8, avec glucides et lipides","Environ 1,5, en hyperventilation forcée","Environ 5, en effort maximal"],"r":1,"e":"QR = VCO₂/VO₂. ~1,0 si glucides purs, ~0,7 si lipides purs. Au repos : ~0,8 (mélange). À l'effort intense : tend vers 1,0 (glucides dominants).","s":4},{"q":"Au-delà du VO₂max, l'énergie supplémentaire provient de :","o":["La filière aérobie, qui continue d'augmenter","Le métabolisme anaérobie, avec du lactate","Le repos, entre deux efforts","Aucune source, l'effort devant s'arrêter aussitôt"],"r":1,"e":"Au-delà du VO₂max, poumons/cœur/muscles ont atteint leur limite. L'effort supplémentaire est couvert par le métabolisme anaérobie (lactate). Il fournit 10 à 20 % de l'énergie à la vitesse du VO₂max.","s":4},{"q":"Les fibres musculaires de type I sont :","o":["Rapides, glycolytiques et vite fatigables","Lentes, oxydatives et résistantes à la fatigue","Inexistantes chez l'humain, seulement chez l'animal","Identiques aux fibres de type IIb"],"r":1,"e":"Type I : lentes, oxydatives, rouges (myoglobine), nombreuses mitochondries, résistantes à la fatigue. Marathon. Type IIa : intermédiaires. Type IIb/IIx : rapides, glycolytiques, fatiguent vite. Sprint. Elles sont riches en mitochondries et en myoglobine.","s":4},{"q":"Le déficit en O₂ correspond à :","o":["Une asphyxie, par manque d'air","Le manque d'O₂ au début de l'effort","L'EPOC, après la fin de l'effort","Un manque génétique d'hémoglobine"],"r":1,"e":"Déficit en O₂ : au début d'un effort, le métabolisme aérobie n'est pas encore à son régime → recours au système anaérobie. Plus faible chez l'athlète entraîné (stabilisation rapide). Il précède la stabilisation du VO₂.","s":4},{"q":"Le couplage excitation-contraction implique :","o":["Aucune protéine → PA seul → contraction","PA → DHPR → RyR → Ca²⁺ → troponine → glissement","Diffusion simple → Ca²⁺ → contraction","Endocytose → vésicules de Ca²⁺ → libération d'actine"],"r":1,"e":"PA propagé par tubule T → activation DHPR (canal voltage-dépendant) → ouverture du récepteur RyR du RS → libération massive de Ca²⁺ → fixation sur troponine C → déplacement de la tropomyosine → contraction. Le DHPR est dans le tubule T et le RyR dans le RS.","s":4},{"q":"L'organisation hiérarchique du muscle inclut :","o":["Le muscle entier et son épimysium","Le fascicule et son périmysium","La fibre musculaire et son endomysium","La myofibrille et ses sarcomères","Les filaments d'actine et de myosine","Le motoneurone alpha et sa plaque"],"r":[0,1,2,3,4],"e":"Hiérarchie : muscle (épimysium) → fascicule (périmysium) → fibre (endomysium) → myofibrille → filaments épais (myosine) + fins (actine). Le motoneurone appartient au système nerveux : c'est l'unité fonctionnelle de commande, pas un niveau de l'emboîtement structural du muscle.","s":4},{"q":"Un perchiste réalise un saut de quelques secondes. Quelle filière fournit surtout l'énergie ?","o":["Le système ATP-PCr, avec la phosphocréatine","La filière aérobie, par l'oxydation des lipides","La glycolyse anaérobie seule, au bout de 2 minutes","La néoglucogenèse du foie, à partir du lactate et de l'ATP"],"r":0,"e":"Un effort explosif de moins de 10 secondes puise dans l'ATP et la phosphocréatine stockés dans le muscle : c'est la filière qui s'active le plus vite, mais elle s'épuise en une dizaine de secondes.","s":4},{"q":"Le débit cardiaque maximal à l'exercice atteint :","o":["10 L/min","15-20 L/min","25-30 L/min","50 L/min"],"r":2,"e":"DC max ~25-30 L/min (×5-6 par rapport au repos à 5 L/min).","s":4},{"q":"La FC d'un athlète au repos vs effort suit un facteur :","o":["×2","×4","×6","×10"],"r":2,"e":"Athlète : FC max ≈ 6× FC repos. Personne normale : ≈ 4×.","s":4},{"q":"Un marathonien court plus de 2 heures. D'où vient surtout son énergie ?","o":["De la filière aérobie, avec glycogène puis lipides","Du système ATP-PCr, renouvelé en continu","De la glycolyse anaérobie, avec du lactate tout du long","Des protéines musculaires uniquement"],"r":0,"e":"Pour un effort modéré prolongé, le métabolisme aérobie domine : il oxyde d'abord le glycogène (musculaire et hépatique) puis les lipides. Quand les réserves de glycogène s'épuisent, le coureur doit ralentir.","s":4},{"q":"La réserve d'ATP déjà présente dans le muscle permet à elle seule :","o":["Quelques secondes de contraction","Environ 10 minutes d'effort","Une heure d'effort modéré","Toute une journée de marche"],"r":0,"e":"Le muscle stocke très peu d'ATP (~6 mM/kg) : quelques secondes. La phosphocréatine le reconstitue aussitôt, jusqu'à une dizaine de secondes, puis la glycolyse et l'aérobie prennent le relais.","s":4},{"q":"Le volume courant à l'exercice se stabilise à :","o":["~30% de la capacité vitale","~60% de la capacité vitale","~90% de la capacité vitale","100%"],"r":1,"e":"VT plafonne à ~60% de la capacité vitale ; au-delà, c'est la fréquence qui augmente.","s":4},{"q":"L'hyperpnée d'exercice maintient :","o":["Une PO2 et une PCO2 stables","Une hypocapnie, avec une PCO2 basse","Une acidose, avec une PCO2 élevée et prolongée","Une hyperoxie, avec une PO2 haute"],"r":0,"e":"L'hyperpnée d'exercice ne modifie ni PO2, PCO2, ni [H+] plasmatique → maintien de l'homéostasie.","s":4},{"q":"L'effet presseur de l'exercice est plus marqué pour :","o":["Les membres inférieurs","Les membres supérieurs","Le tronc","Identique partout"],"r":1,"e":"Effet presseur (↑ TA) plus marqué pour les exercices avec membres supérieurs.","s":4},{"q":"VO₂max relatif s'exprime en :","o":["L/min","mL/min","mL/kg/min","mL/m²"],"r":2,"e":"VO₂max relatif = mL/kg/min (corrige la masse) ; absolu = L/min.","s":4},{"q":"La phase I de la réponse hyperpnéique débute :","o":["Après 1 minute d'effort","Avec un délai de 30 secondes","Brusquement, dès le début de l'effort","Après le seuil lactique, par l'acidose sanguine"],"r":2,"e":"Phase I : ↑ brusque dès le début, anticipée par le cortex cérébral → centre respiratoire (tronc cérébral). Elle est déclenchée par le cortex cérébral.","s":4},{"q":"En cas de chaleur et humidité élevées, le risque principal est :","o":["L'hypothermie","Le coup de chaleur","La déshydratation seule","La crampe"],"r":1,"e":"Chaleur + humidité élevées → la transpiration ne suffit plus → coup de chaleur, refroidissement artificiel nécessaire.","s":4},{"q":"Le fascicule musculaire est entouré par :","o":["Le périmysium","L'épimysium","L'endomysium","Le sarcolemme"],"r":0,"e":"L'épimysium entoure le muscle entier et l'endomysium la fibre musculaire.","s":4},{"q":"La plasticité des fibres musculaires permet :","o":["La conversion des fibres et leur hypertrophie","La seule hypertrophie des fibres","La seule conversion des fibres, sans hypertrophie","Aucune adaptation à l'entraînement"],"r":0,"e":"C'est le fondement physiologique de l'adaptation à l'entraînement. La densité mitochondriale augmente aussi.","s":4},{"q":"L'alimentation du sportif comporte une part protéique de :","o":["12 %","15 %","20 %","30 %"],"r":0,"e":"Les glucides y montent à 60-70 %, contre 50 % en population générale ; le fer et le calcium demandent une attention particulière.","s":4},{"q":"La part de graisses saturées recommandée est :","o":["Au maximum 10 %","30 %","15 %","Sans limite"],"r":0,"e":"Les lipides insaturés sont à privilégier, dans un total lipidique de 30 % pour la population générale.","s":4},{"q":"L'alcool est déconseillé car il apporte :","o":["Des calories vides, et un effet diurétique","Des glucides rapides, utiles à l'effort","Des protéines, pour la récupération","Des lipides, en réserve pour l'endurance longue"],"r":0,"e":"La modération du sel est par ailleurs recommandée, surtout en cas d'hypertension. Il favorise ainsi la déshydratation.","s":4},{"q":"Par forte chaleur, comment le corps évacue-t-il la chaleur ?","o":["La transpiration, par évaporation de la sueur","La vasodilatation cutanée, vers la peau","La ventilation accrue, qui expulse l'air chaud","La vasoconstriction cutanée, qui garde la chaleur","Les frissons, par contractions musculaires"],"r":[0,1,2],"e":"Vasodilatation cutanée, transpiration et ventilation font perdre de la chaleur. Vasoconstriction et frissons servent au contraire à lutter contre le froid. Si la sueur ne s'évapore plus (chaleur + humidité), risque de coup de chaleur.","s":4},{"q":"Le débit musculaire au repos représente :","o":["15 à 20 % du débit cardiaque","Environ 5 % du débit cardiaque","La moitié du débit cardiaque","80 % du débit cardiaque"],"r":0,"e":"C'est une multiplication par 20 du débit musculaire absolu. Il atteint 15 à 20 L/min à l'effort.","s":4},{"q":"La fréquence cardiaque de l'athlète, du repos à l'effort, est multipliée par :","o":["6, contre 4 chez une personne non entraînée","2, comme chez une personne sédentaire et âgée","4, comme chez tout le monde","10, grâce à une réserve très large"],"r":0,"e":"Sa fréquence de repos plus basse lui donne une réserve plus grande.","s":4},{"q":"Combien de stades de sommeil distingue-t-on ?","o":["2, le sommeil calme et le sommeil agité","3, l'endormissement, le léger et le profond","4 à 5, le sommeil lent et le paradoxal","Une seule phase, continue toute la nuit sans cycle"],"r":2,"e":"Sommeil = lent (NREM, stades N1, N2, N3) + paradoxal (REM). Cycle ~90 min, répété 4-6× par nuit. Le sommeil lent compte 3 à 4 stades, et le paradoxal correspond au REM.","s":5},{"q":"Quelle hormone régule le rythme veille-sommeil ?","o":["Le cortisol, sécrété par la surrénale au réveil","La mélatonine, sécrétée par la pinéale","L'insuline, sécrétée par le pancréas","La TSH, sécrétée par l'hypophyse"],"r":1,"e":"Mélatonine : sécrétée par la pinéale en l'absence de lumière (nuit). Synchronise le rythme circadien et favorise l'endormissement. Inhibée par la lumière. Elle est sécrétée la nuit.","s":5},{"q":"Le rythme circadien dure environ :","o":["12 heures","24 heures","48 heures","1 semaine"],"r":1,"e":"Rythme circadien ≈ 24h (en réalité ~24h11 min recalibré chaque jour par la lumière). Horloge maître = noyau suprachiasmatique de l'hypothalamus.","s":5},{"q":"L'hormone du stress qui pic le matin est :","o":["La mélatonine, sécrétée la nuit par la pinéale","Le cortisol, pour préparer le réveil","L'insuline, après le petit-déjeuner","La progestérone, en phase lutéale"],"r":1,"e":"Cortisol : pic matinal (6-9h) pour préparer au réveil et à l'activité. Diminue progressivement, nadir vers minuit. Antagoniste de la mélatonine. Son pic se situe entre 6 et 9 h.","s":5},{"q":"La température centrale est régulée autour de :","o":["35°C","36-37°C","38-39°C","40°C"],"r":1,"e":"Température centrale = 36,5-37,5°C, régulée par l'hypothalamus. Suit un rythme circadien (min ~4h, max ~17-19h). >38°C = fièvre.","s":5},{"q":"L'organisme est composé de combien de systèmes principaux ?","o":["3 systèmes principaux","5 systèmes principaux","11 systèmes principaux","20 systèmes principaux"],"r":2,"e":"11 systèmes organiques principaux. Travaillent ensemble pour maintenir l'homéostasie. Beaucoup d'organes contribuent à plusieurs systèmes. Ce sont les systèmes nerveux, endocrinien, cardiovasculaire, respiratoire, immunitaire, digestif, urinaire, musculaire, squelettique, tégumentaire et reproducteur.","s":5},{"q":"L'horloge biologique principale se trouve dans :","o":["Le cœur, par son rythme sinusal","Le foie, par ses cycles métaboliques propres","Le noyau suprachiasmatique de l'hypothalamus","L'estomac, par la ghréline des repas"],"r":2,"e":"Le noyau suprachiasmatique (NSC) de l'hypothalamus est l'horloge maître. Reçoit l'info lumineuse via le tract rétino-hypothalamique.","s":5},{"q":"Quelle glande sécrète la mélatonine ?","o":["L'hypothalamus antérieur","La glande pinéale, ou épiphyse","L'hypophyse, ou glande pituitaire","La surrénale, ou glande adrénale"],"r":1,"e":"La glande pinéale (épiphyse) sécrète la mélatonine sous contrôle du NSC : pic ≈ 2h, début ≈ 21h, arrêt ≈ 7h30.","s":5},{"q":"Combien d'heures de sommeil sont recommandées pour un adulte ?","o":["3-4 heures","5-6 heures","7-9 heures","12-14 heures"],"r":2,"e":"Adulte : 7-9 heures de sommeil/nuit recommandées. Variabilité individuelle. Privation chronique = effets délétères cognitifs, cardiométaboliques, immunitaires.","s":5},{"q":"Le rôle physiologique principal du sommeil paradoxal (REM) est :","o":["La récupération musculaire, par le repos","La consolidation de la mémoire et des émotions","L'élimination des déchets, par le système glymphatique","La croissance osseuse, la nuit"],"r":1,"e":"REM (mouvements oculaires rapides) : rêves vifs, consolidation mémoire (procédurale, émotionnelle), traitement émotionnel. Atonie musculaire mais activité cérébrale intense. Il s'accompagne de rêves intenses.","s":5},{"q":"Le mécanisme principal de thermorégulation en cas de chaleur est :","o":["Les frissons des muscles squelettiques","La vasoconstriction de la peau","La vasodilatation cutanée et la sudation","La hausse du métabolisme de base"],"r":2,"e":"Chaleur : hypothalamus → vasodilatation cutanée (transfert thermique) + sudation (évaporation = principal mécanisme). Froid : vasoconstriction + frissons.","s":5},{"q":"Le débit sanguin postprandial est augmenté vers :","o":["Les muscles squelettiques, au repos","Le tube digestif, d'où la somnolence","Le cerveau, pour la vigilance","Les reins, pour la filtration"],"r":1,"e":"Postprandial : sang redirigé vers le tube digestif (jusqu'à 30% du DC) pour absorption → d'où la somnolence et la contre-indication d'effort intense après repas copieux.","s":5},{"q":"Le stress aigu active le système :","o":["Parasympathique, par le nerf vague et l'acétylcholine","Sympathique, par les catécholamines","Endocrinien thyroïdien seul, par la T4","Aucun système, la réponse étant locale"],"r":1,"e":"Stress aigu = activation sympathique (« fight or flight ») : libération adré/noradré → ↑ FC, ↑ PA, ↑ contractilité, vasoconstriction splanchnique, vasodilatation musculaire. La FC et la PA augmentent.","s":5},{"q":"L'activité physique régulière diminue le risque de :","o":["Diabète, maladies cardiovasculaires et dépression","Croissance osseuse harmonieuse, chez l'enfant","Bonne fonction cognitive, à tout âge","Densité musculaire, chez la personne âgée"],"r":0,"e":"≥150 min/sem d'AP modérée → ↓ diabète T2, MCV, certains cancers (côlon, sein), dépression, démence, ostéoporose. Recommandations OMS. Certains cancers en font aussi partie.","s":5},{"q":"Pendant un jeûne prolongé (>24h), la principale source d'énergie est :","o":["Le glycogène, déjà épuisé","Les lipides, par la β-oxydation","Le glucose plasmatique, en continu","Le lactate, recyclé par le foie en glucose"],"r":1,"e":"Après ~24h, le glycogène hépatique est épuisé. L'organisme passe aux lipides : β-oxydation → corps cétoniques (utilisables par cerveau et muscles). Protéolyse limitée. Ils donnent des corps cétoniques.","s":5},{"q":"Une privation chronique de sommeil entraîne :","o":["Aucune conséquence notable, même à long terme","Une altération cognitive et une immunodépression","Une amélioration de la performance physique","Une baisse isolée de la fréquence cardiaque"],"r":1,"e":"Privation chronique : ↓ attention/mémoire, immunodépression, résistance à l'insuline, prise de poids, ↑ MCV, ↑ dépression, ↓ performance physique. Le risque cardiométabolique et les troubles de l'humeur augmentent aussi.","s":5},{"q":"Le pic de l'hormone de croissance (GH) se produit :","o":["Au matin, avec le pic de cortisol vers 8 h","Pendant le sommeil profond, en N3","À midi, après le repas","En sommeil paradoxal, ou REM"],"r":1,"e":"GH : pic principal pendant le sommeil profond (N3). Rôle dans la réparation tissulaire et la croissance. Privation de sommeil = ↓ sécrétion GH.","s":5},{"q":"La leptine est :","o":["Une hormone de la faim, gastrique","Une hormone de satiété, élevée la nuit","Une hormone du stress, sécrétée par la surrénale","Une hormone proche de l'insuline"],"r":1,"e":"Leptine = hormone de satiété (sécrétée par le tissu adipeux). Niveaux nocturnes ↑, diminuent en début de journée. La privation de sommeil ↓ leptine et ↑ ghréline → faim accrue.","s":5},{"q":"Une élévation de la pression artérielle survient typiquement :","o":["Vers minuit, pendant le sommeil","Le matin, avec une montée rapide vers 6 h 45","Jamais, la pression restant stable sur 24 heures","À 19 h uniquement, après le travail"],"r":1,"e":"PA : montée rapide vers 6h45 (cortisol, sympathique). Pic vers 18h30. Min vers 2h. C'est pourquoi la fréquence des AVC/IDM est plus élevée en matinée. Cela explique le risque cardiovasculaire matinal.","s":5},{"q":"La synthèse de mélatonine suit la voie :","o":["Tryptophane → sérotonine → mélatonine","Glucose → pyruvate → lactate → mélatonine","Cholestérol → testostérone → mélatonine","ATP → ADP → AMPc → mélatonine"],"r":0,"e":"Tryptophane (AA) → 5-hydroxytryptophane → sérotonine → N-acétylsérotonine (NAS) → mélatonine. Synthèse stimulée par l'obscurité, inhibée par la lumière. Les intermédiaires sont le 5-hydroxytryptophane et la N-acétylsérotonine.","s":5},{"q":"Le décalage horaire (jet lag) est dû à :","o":["Une infection contractée en voyage","Un décalage entre l'horloge interne et le jour","Un excès de mélatonine, produite dans l'avion","Une déshydratation, liée à l'air sec"],"r":1,"e":"Jet lag : désynchronisation NSC vs lumière externe lors d'un voyage transméridien. Effets sur sommeil, vigilance, digestion. Réajustement ~1 jour/fuseau.","s":5},{"q":"L'efficacité cardiovasculaire et la force musculaire sont maximales vers :","o":["6h","12h","17h","23h"],"r":2,"e":"Performances physiques (force, coordination, efficacité CV) maximales en fin d'après-midi (~17h), pic de température centrale ~19h. Min en début de matinée.","s":5},{"q":"Le diabète illustre l'interconnexion des systèmes en affectant :","o":["Un seul système, l'endocrinien","Plusieurs systèmes, de l'endocrinien au nerveux","Le cerveau seul, par l'hypoglycémie","Aucun système, la maladie étant purement sanguine"],"r":1,"e":"Diabète : endocrinien (insuline) + immunitaire (cicatrisation) + urinaire (néphropathie) + cardiovasculaire (microangiopathie, AVC, IDM) + nerveux (neuropathie). Tout est interconnecté. Il touche les systèmes endocrinien, immunitaire, cardiovasculaire, urinaire et nerveux.","s":5},{"q":"La voie d'entrée de la lumière vers la mélatonine est :","o":["Cerveau seul → cortex visuel V1 → hypophyse → mélatonine","Rétine → tract rétino-hypothalamique → NSC → pinéale","Peau → foie → sang → mélatonine","Inconscient → cortex → mélatonine"],"r":1,"e":"Lumière captée par la rétine (cônes, bâtonnets, cellules ganglionnaires intrinsèquement photosensibles) → tract rétino-hypothalamique → NSC → contrôle pinéale → mélatonine.","s":5},{"q":"Le SAD (Seasonal Affective Disorder) est lié à :","o":["Un excès de soleil → ↓ mélatonine","Moins de lumière → ↑ mélatonine → humeur basse","Une infection saisonnière, en hiver","Une carence en fer → anémie → fatigue de l'hiver"],"r":1,"e":"SAD = dépression saisonnière (hiver). Liée à la diminution de la lumière → désynchronisation circadienne, ↑ mélatonine en journée. Traitement : luminothérapie. Il survient en hiver.","s":5},{"q":"L'axe HPA (hypothalamo-hypophyso-surrénalien) en réponse au stress chronique :","o":["Diminue la sécrétion de cortisol","Maintient un cortisol élevé → effets délétères","N'a aucun effet, l'axe s'adaptant toujours au stress","Augmente la mélatonine → somnolence"],"r":1,"e":"Stress chronique → activation soutenue de l'axe CRH-ACTH-cortisol → effets nocifs : immunosuppression, ostéoporose, dépression, atrophie hippocampique, syndrome métabolique. Ces effets sont l'immunosuppression, le syndrome métabolique et l'atrophie de l'hippocampe.","s":5},{"q":"La réponse de peur active rapidement :","o":["Le cortex préfrontal seul → analyse lente","L'amygdale → tronc cérébral → réponse sympathique","Le cervelet seul → coordination de la fuite et du combat","Aucune voie → réponse locale"],"r":1,"e":"Peur : voie courte amygdale (analyse rapide) → réponse sympathique immédiate. Voie longue passe par le cortex pour analyse plus fine et contrôle de la réponse. La réponse survient en quelques millisecondes.","s":5},{"q":"La sénescence (vieillissement) implique :","o":["Aucun changement, jusqu'à 80 ans","Une baisse des hormones, des muscles et de l'immunité","Une augmentation de la taille de tous les organes","Aucune perte fonctionnelle, grâce à la compensation des organes"],"r":1,"e":"Vieillissement : sarcopénie (↓ masse musc), ostéoporose (↓ os), ↓ hormones sexuelles, ↓ GH, ↓ immunité, ↓ thermorégulation, ↓ fonction cognitive. D'où l'importance de l'AP régulière. La masse osseuse et la thermorégulation diminuent aussi.","s":5},{"q":"Tumeurs ou ablation du NSC entraînent :","o":["Aucun effet, l'horloge étant redondante","Une désynchronisation du cycle veille-sommeil","Une hypertension, par atteinte du tronc cérébral","Un diabète, par atteinte de l'hypophyse"],"r":1,"e":"Lésions du noyau suprachiasmatique → perte de l'horloge maître → désorganisation du cycle veille/sommeil et des autres rythmes circadiens (température, hormones).","s":5},{"q":"Les cycles infraradiens (>24h) incluent :","o":["Le rythme cardiaque, de 60 à 80 par minute","Le cycle menstruel, d'environ 28 jours","La respiration, de 12 à 20 cycles par minute au repos","Le cycle veille-sommeil, de 24 heures"],"r":1,"e":"Cycles infraradiens (durée > 24h) : cycle menstruel (~28j), variations saisonnières (T3/T4 plus basses en hiver, mélatonine plus élevée). Cycles ultradiens : <24h (impulsions hormonales, REM/NREM). Les variations saisonnières de T3, T4 et mélatonine en font aussi partie.","s":5},{"q":"Le pic de cortisol survient typiquement vers :","o":["2h du matin","9h","15h","21h"],"r":1,"e":"Cortisol : pic vers 9h (vigilance/métabolisme), minimum en milieu de nuit.","s":5},{"q":"Le pic de mélatonine survient vers :","o":["Vers 2 h du matin","Vers 9 h du matin","Vers 15 h, l'après-midi","Vers 17 h, en fin de journée"],"r":0,"e":"Mélatonine : début ~21h, pic ~2h, arrêt ~7h30. Inhibée par la lumière.","s":5},{"q":"La température corporelle minimale est observée vers :","o":["2h","4h","9h","19h"],"r":1,"e":"Température min ~4h, pic max ~19h. La mélatonine ↑ quand la T° ↓.","s":5},{"q":"L'hormone de croissance (GH) atteint son pic :","o":["Au réveil","Pendant le sommeil profond","En milieu d'après-midi","Le soir"],"r":1,"e":"GH : pic pendant le sommeil profond (réparation tissulaire, croissance).","s":5},{"q":"La ghréline est :","o":["Une hormone de satiété, sécrétée par le tissu adipeux","Une hormone de la faim, sécrétée par l'estomac","Une hormone thyroïdienne, comme la T4","Un neurotransmetteur du sommeil paradoxal"],"r":1,"e":"La ghréline est le miroir de la leptine : produite par la muqueuse gastrique, son pic précède les repas et stimule l'appétit via l'hypothalamus. La privation de sommeil augmente la ghréline et abaisse la leptine, ce qui explique la prise de poids associée au manque de sommeil. Elle s'élève avant les repas.","s":5},{"q":"Parmi ces molécules, lesquelles sont des hormones réglées par l'horloge biologique ?","o":["La mélatonine","Le cortisol","L'hormone de croissance (GH)","La pepsine","La trypsine (enzyme pancréatique)","L'amylase salivaire"],"r":[0,1,2],"e":"Mélatonine (pic vers 2 h), cortisol (pic le matin) et GH (pendant le sommeil profond) suivent le rythme circadien. Pepsine, trypsine et amylase sont des enzymes digestives, pas des hormones.","s":5},{"q":"Le temps de réaction le plus rapide est vers :","o":["10h","15h30","19h","23h"],"r":1,"e":"Temps de réaction le plus rapide ~15h30. Meilleure coordination ~14h30.","s":5},{"q":"Le syndrome général d'adaptation au stress (Selye) comprend :","o":["Alarme → Résistance → Épuisement","Choc → Fuite → Combat → Récupération","Tension → Détente → Repos","Anxiété → Phobie → Trauma"],"r":0,"e":"3 phases : Alarme (réaction immédiate) → Résistance (adaptation) → Épuisement (les défenses sont dépassées).","s":5},{"q":"Le rythme circadien est synchronisé par :","o":["L'alternance de la lumière et de l'obscurité","Les variations de température extérieure","Les biorythmes mensuels, comme le cycle","Les rythmes saisonniers, sur l'année"],"r":0,"e":"Rythme circadien (24h) synchronisé principalement avec l'alternance lumière/obscurité.","s":5},{"q":"La période où le risque cardiovasculaire est maximal (montée brusque de TA) est :","o":["Vers 2h","Vers 6h45","Vers 14h","Vers 22h"],"r":1,"e":"Vers 6h45 : montée brutale de la TA → ↑ risque cardiovasculaire (infarctus matinal).","s":5},{"q":"L'arrêt de la sécrétion de mélatonine survient :","o":["Vers 21h","Vers 4h","Vers 7h30","Vers 12h"],"r":2,"e":"Mélatonine : début ~21h, pic ~2h, arrêt ~7h30 (réveil).","s":5},{"q":"Les 4 systèmes affectés par le diabète sont :","o":["Le système endocrinien","Le système immunitaire","Le système urinaire","Le système cardiovasculaire","Le système squelettique"],"r":[0,1,2,3],"e":"Diabète : affecte endocrinien (cause), immunitaire (cicatrisation), urinaire (rein), cardio (vaisseaux + rétine). Ils sont touchés par la glycémie, la cicatrisation, les lésions rénales et vasculaires.","s":5},{"q":"Le principe fondamental de l'intégration des systèmes énonce que :","o":["Les systèmes coopèrent, un organe servant à plusieurs","Chaque organe n'appartient qu'à un seul système","Les systèmes sont indépendants les uns des autres","Seul le système nerveux coordonne, sans aide hormonale"],"r":0,"e":"Le cerveau appartient ainsi aux systèmes nerveux et endocrinien, et le sternum aux systèmes squelettique, immunitaire et cardiovasculaire.","s":5},{"q":"Le système respiratoire participe, outre les échanges gazeux :","o":["À la régulation de la température","À la digestion","À la production de cellules sanguines","Au contrôle du pH urinaire"],"r":0,"e":"Le système cardiovasculaire y contribue également, en plus du transport des matériaux.","s":5},{"q":"Le système squelettique assure, outre le soutien et la protection :","o":["Le mouvement et la formation des cellules du sang","La digestion, par les enzymes stockées dans l'os","L'immunité spécifique, par les anticorps du sang","La thermorégulation seule, par la moelle"],"r":0,"e":"Le système tégumentaire assure, lui, soutien, protection et régulation des liquides.","s":5},{"q":"Les impulsions, parmi les biorythmes, correspondent :","o":["À une libération hormonale en jets, comme l'insuline","Au cycle de 24 heures, réglé par la lumière du jour","Au cycle menstruel, d'environ 28 jours","Aux variations saisonnières, sur une année"],"r":0,"e":"Les quatre types cités sont impulsions, rythme circadien, cycle mensuel et variations saisonnières. Elle se fait sur des minutes ou des heures.","s":5},{"q":"Parmi les variations saisonnières, le cours cite :","o":["Des T3 et T4 basses et une mélatonine élevée en hiver","Une mélatonine plus basse en hiver, faute de nuit","Des T3 et T4 élevées en hiver, contre le froid","Aucune variation, les hormones restant stables toute l'année"],"r":0,"e":"Ces cycles dépassent 24 heures et relèvent des rythmes infradiens.","s":5},{"q":"À 6 h 45, l'événement circadien marquant est :","o":["Une montée rapide de la pression artérielle","Le pic de sécrétion du cortisol","L'arrêt de la sécrétion de mélatonine, au réveil","La température corporelle minimale"],"r":0,"e":"L'arrêt de la sécrétion de mélatonine survient vers 7 h 30 et le pic de cortisol vers 9 h. C'est une période de risque cardiovasculaire.","s":5},{"q":"La meilleure coordination survient vers :","o":["14 h 30","15 h 30","17 h","10 h"],"r":0,"e":"Le temps de réaction le plus rapide se situe vers 15 h 30 et l'efficacité cardiovasculaire maximale vers 17 h.","s":5},{"q":"La pression artérielle maximale survient vers :","o":["18 h 30","6 h 45","19 h","21 h"],"r":0,"e":"La température corporelle maximale survient vers 19 h et le début de la sécrétion de mélatonine vers 21 h.","s":5}]};
